(function(A){Object.assign(A.D,{"G318":{"l":"ἀνάγκη","o":17,"ar":"<f><o>ἀνάγκη</o>، <g>-ης, ἡ </g></f> <s n=\"1.\"><b>ضرورة، اضطرار</b>: <g>ἔχειν ἀ-</g> مع المصدر: <b>اضطُرّ</b>: <r v=\"Luke.14.18\"></r>، <r v=\"Luke.23.17\"></r>، <r v=\"1Cor.7.37\"></r>، <r v=\"Jude.1.3\"></r>، <r v=\"Heb.7.27\"></r>؛ <g>ἐξ ἀ., κατ</g>' <g>ἀ.</g>: <b>اضطرارًا، بالضرورة</b>: <r v=\"2Cor.9.7\"></r>، <r v=\"Heb.7.12\"></r>، <r v=\"Phlm.1.14\"></r>؛ <g>ἀ. μοι ἐπίκειται</g>: <i>الضرورة موضوعة عليّ</i>: <r v=\"1Cor.9.16\"></r>؛ مع المصدر (= <g>ἀναγκαῖον ἐστι</g>): <r v=\"Matt.18.7\"></r>، <r v=\"Rom.13.5\"></r>، <r v=\"Heb.9.16\"></r>، <r v=\"Heb.9.23\"></r> </s> <s n=\"2.\"><b>قسر</b>، <b>عنف</b>، ومن هنا <b>ألم</b>، <b>ضيق، شدة</b> (قارن <g>θλίψις</g>): <r v=\"Luke.21.23\"></r>، <r v=\"1Cor.7.26\"></r>، <r v=\"1Thess.3.7\"></r>؛ في الجمع، <g>ἐν ἀ.</g>: <r v=\"2Cor.6.4\"></r>، <r v=\"2Cor.12.10\"></r>.†</s>","en":"<f><o>ἀνάγκη</o>, <g>-ης, ἡ </g></f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H4689\">מָצוֹק</h>, <h n=\"H6862\">צַר</h>;]</e> </et> <s n=\"1.\"><b>necessity</b>: <g>ἔχειν ἀ-</g>, c. inf., <b>to be compelled</b>, <r v=\"Luke.14.18\"></r> <r v=\"Luke.23.17\"></r> (Rec., R, mg.), <r v=\"1Cor.7.37\"></r>, <r v=\"Jude.1.3\"></r>, <r v=\"Heb.7.27\"></r>; <g>ἐξ ἀ., κατ</g>' <g>ἀ.</g>, <b>of necessity</b>, <r v=\"2Cor.9.7\"></r>, <r v=\"Heb.7.12\"></r>, <r v=\"Phlm.1.14\"></r>; <g>ἀ. μοι ἐπίκειται</g>, <i>n. is laid on me</i>, <r v=\"1Cor.9.16\"></r>; c. inf. (= <g>ἀναγκαῖον ἐστι</g>), <r v=\"Matt.18.7\"></r>, <r v=\"Rom.13.5\"></r>, <r v=\"Heb.9.16\"></r>, <r v=\"Heb.9.23\"></r> </s> <s n=\"2.\"><b>force</b>, <b>violence</b>, hence <b>pain</b>, <b>distress</b> (Diod., al.; LXX; v. M, <i>Th.</i>, 41; MM, <i>VGT</i>, s.v.; cf. <g>θλίψις</g>): <r v=\"Luke.21.23\"></r>, <r v=\"1Cor.7.26\"></r>, <r v=\"1Thess.3.7\"></r>; pl. (v. Bl., § 32, 6; Swete, <i>Mk.</i>, 153), <g>ἐν ἀ.</g>, <r v=\"2Cor.6.4\"></r> <r v=\"2Cor.12.10\"></r>.†</s>"},"G373":{"l":"ἀναπαύω","o":12,"ar":"<f><o>ἀνα-παύω</o>،</f> <s><b>أعطى فترة راحة من التعب</b>، <b>أراح</b>، <b>أنعش</b>: <r v=\"Matt.11.28\"></r>، <r v=\"1Cor.16.18\"></r>، <r v=\"Phlm.1.20\"></r>؛ المبني للمجهول: <r v=\"Phlm.1.7\"></r>، <r v=\"2Cor.7.13\"></r>. الصيغة الوسطى: <b>استراح</b>، <b> نال الراحة، تمتع بالراحة</b>: <r v=\"Matt.26.45\"></r>، <r v=\"Mark.6.31\"></r>، <r v=\"Mark.14.41\"></r>، <r v=\"Luke.12.19\"></r>، <r v=\"Rev.6.11\"></r>، <r v=\"Rev.14.13\"></r>؛ وكما في العبرية في <r v=\"Isa.11.2\"></r> (<h n=\"H5117,H5921\">נוּחַ עַל</h>)، <g>τὸ πνεῦμα ἐφ</g>' <g>ὑμᾶς ἀ.</g>: <r v=\"1Pet.4.14\"></r>. (قارن <r v=\"Lev.26.34\"></r> وما يليه.)†</s>","en":"<f><o>ἀνα-παύω</o>,</f> <et> <e t=\"septuagint\">[in LXX for fourteen different words, chiefly <h n=\"H5117\">נוּחַ</h>, also <h n=\"H7257\">רָבַץ</h>, <h n=\"H7599\">שָׁאַן</h>, etc.;],</e> </et> <s><b>to give intermission from labour</b>, <b>to give rest</b>, <b>refresh</b>: <r v=\"Matt.11.28\"></r>, <r v=\"1Cor.16.18\"></r>, <r v=\"Phlm.1.20\"></r>; pass., <r v=\"Phlm.1.7\"></r>, <r v=\"2Cor.7.13\"></r>. Mid., <b>to ta</b>, <b> rest, enjoy rest</b>: <r v=\"Matt.26.45\"></r>, <r v=\"Mark.6.31\"></r> <r v=\"Mark.14.41\"></r>, <r v=\"Luke.12.19\"></r>, <r v=\"Rev.6.11\"></r> <r v=\"Rev.14.13\"></r>; as in <i>Heb.</i> of <r v=\"Isa.11.2\"></r> (<h n=\"H5117,H5921\">נוּחַ עַל</h>), <g>τὸ πνεῦμα ἐφ</g>' <g>ὑμᾶς ἀ.</g>, <r v=\"1Pet.4.14\"></r>. (In <g>π.</g> this word is used as a technical agricultural term; v. MM, <i>VGT</i>, s.v.; and cf. <r v=\"Lev.26.34\"></r> f.; Cremer, 826.)†</s>"},"G375":{"l":"ἀναπέμπω","o":5,"ar":"<f>* <o>ἀνα-πέμπω </o></f> <s n=\"1.\"><b>أرسل إلى فوق</b>، <s n=\"(a)\">في اليونانية الكلاسيكية: إلى مكان أعلى؛ </s> <s n=\"(b)\">إلى سلطة أعلى: <r v=\"Luke.23.7\"></r>، <r v=\"Luke.23.15\"></r>، <r v=\"Acts.25.21\"></r>.</s> </s> <s n=\"2.\"><b>أعاد، ردّ</b>: <r v=\"Luke.23.11\"></r>، <r v=\"Phlm.1.11\"></r>.†</s>","en":"<f>* <o>ἀνα-πέμπω </o></f> <s n=\"1.\"><b>to send up</b>, <s n=\"(a)\">to a higher place (Æsch., Plat., al.); </s> <s n=\"(b)\">to a higher authority (Deiss., BS, 229; MM, <i>VGT</i>, s.v.; cf. also Field, <i>Notes</i>, 140): <r v=\"Luke.23.7\"></r>, <r v=\"Luke.23.15\"></r>, <r v=\"Acts.25.21\"></r>.</s> </s> <s n=\"2.\"><b>to send back</b> (Pind.): <r v=\"Luke.23.11\"></r>, <r v=\"Phlm.1.11\"></r>.†</s>"},"G305":{"l":"ἀναβαίνω","o":82,"ar":"<f><o>ἀναβαίνω</o>،</f> <s><b>يصعد</b>، <b>يرتقي</b>، <s n=\"(a)\">عن الأشخاص: <g>ἐπί συκομωρέαν</g>، <r v=\"Luke.19.4\"></r>؛ <g>εἰς τ. πλοῖον</g>، <r v=\"Mark.6.51\"></r>؛ <g>εἰς Ἱεροσόλυμα</g>، <r v=\"Matt.20.17\"></r>؛ <g>εἰς τ. ἱερόν</g>، مع المصدر، <r v=\"Luke.18.10\"></r>؛ مع ذكر مكان الانطلاق، <r v=\"Matt.3.16\"></r> (<g>ἀπό</g>)، <r v=\"Acts.8.39\"></r> (<g>ἐκ</g>)؛ </s> <s n=\"(b)\">عن الأشياء، <b>يطلع</b>، <b>ينبت</b>، <b>يخرج إلى فوق</b>: سمكة، <r v=\"Matt.17.27\"></r>؛ دخان، <r v=\"Rev.8.4\"></r>؛ نباتات نامية، <r v=\"Matt.13.7\"></r>؛ مجازيًا، عن الأمور التي تخطر على قلب المرء (كالعبرية <h n=\"H5927,H413,H3820\">עָלָה אֶל לֵב</h>؛ <r v=\"2Kgs.12.4\"></r>، وفي مواضع أخرى)، <r v=\"Luke.24.38\"></r>، <r v=\"1Cor.2.9\"></r>؛ وعن الصلوات، <r v=\"Acts.10.4\"></r>؛ والأخبار، <r v=\"Acts.21.31\"></r>. </s> </s>","en":"<f><o>ἀναβαίνω</o>,</f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H5927\">עלה</h>;]</e> </et> <s><b>to go up</b>, <b>ascend</b>, <s n=\"(a)\">of persons: <g>ἐπί συκομωρέαν</g>, <r v=\"Luke.19.4\"></r>; <g>εἰς τ. πλοῖον</g>, <r v=\"Mark.6.51\"></r>; <g>εἰς Ἱεροσόλυμα</g>, <r v=\"Matt.20.17\"></r>; <g>εἰς τ. ἱερόν</g>, c. inf. (M, <i>Pr.</i>, 205), <r v=\"Luke.18.10\"></r>; with mention of place of departure, <r v=\"Matt.3.16\"></r> (<g>ἀπό</g>), <r v=\"Acts.8.39\"></r> (<g>ἐκ</g>); </s> <s n=\"(b)\">of things, <b>to rise</b>, <b>spring up</b>, <b>come up</b>: a fish, <r v=\"Matt.17.27\"></r>; smoke, <r v=\"Rev.8.4\"></r>; plants growing, <r v=\"Matt.13.7\"></r>; metaph., of things coming up in one's mind (as Heb. <h n=\"H5927,H413,H3820\">עָלָה אֶל לֵב</h>; <r v=\"2Kgs.12.4\"></r>, al.), <r v=\"Luke.24.38\"></r>, <r v=\"1Cor.2.9\"></r>; of prayers, <r v=\"Acts.10.4\"></r>; messages, <r v=\"Acts.21.31\"></r> (for late exx., v. MM, <i>VGT</i>, s.v.). </s> </s>"},"G391":{"l":"ἀναστροφή","o":13,"ar":"<f>** <o>ἀνα-στροφή</o>، <g>-ῆς, ἡ</g>،</f> <s n=\"1.\">في اليونانية الكلاسيكية: <b>انقلاب</b> أو <b>رجوع</b>، <b>استدارة</b>.</s> <s n=\"2.\">عند الكُتّاب المتأخرين (انظر تحت مدخل <x><g>ἀναστρέφω</g></x>، وقارن <r v=\"Jas.3.13\"></r>)، <b>سيرة</b>، <b>تصرّف</b>، <b>سلوك</b>: <r v=\"Gal.1.13\"></r>، <r v=\"Eph.4.22\"></r>، <r v=\"1Tim.4.12\"></r>، <r v=\"Heb.13.7\"></r>، <r v=\"Jas.3.13\"></r>، <r v=\"1Pet.1.15\"></r>، <r v=\"1Pet.1.18\"></r> <r v=\"1Pet.2.12\"></r> <r v=\"1Pet.3.1\"></r>، <r v=\"1Pet.3.2\"></r>، <r v=\"1Pet.3.16\"></r>، <r v=\"2Pet.2.7\"></r> <r v=\"2Pet.3.11\"></r>.†</s>","en":"<f>** <o>ἀνα-στροφή</o>, <g>-ῆς, ἡ</g>,</f> <et> <e t=\"derivation\">(&lt; <x><g>ἀναστρέφομαι</g></x>),</e> <e t=\"septuagint\">[in LXX: <r v=\"Tob.4.14\"></r>, <r v=\"2Macc.5.8\"></r> <r v=\"2Macc.6.23\"></r>*;]</e> </et> <s n=\"1.\"><b>a turning down</b> or <b>back</b>, <b>a wheeling about</b> (Soph., Thuc., al.).</s> <s n=\"2.\">In late writers (Polyb., al.; v.s. <x><g>ἀναστρέφω</g></x>, and cf. Hort on <r v=\"Jas.3.13\"></r>; MM, <i>VGT</i>, s.v.), <b>manner of life</b>, <b>behaviour</b>, <b>conduct</b>: <r v=\"Gal.1.13\"></r>, <r v=\"Eph.4.22\"></r>, <r v=\"1Tim.4.12\"></r>, <r v=\"Heb.13.7\"></r>, <r v=\"Jas.3.13\"></r>, <r v=\"1Pet.1.15\"></r>, <r v=\"1Pet.1.18\"></r> <r v=\"1Pet.2.12\"></r> <r v=\"1Pet.3.1\"></r>, <r v=\"1Pet.3.2\"></r>, <r v=\"1Pet.3.16\"></r>, <r v=\"2Pet.2.7\"></r> <r v=\"2Pet.3.11\"></r>.†</s>"},"G353":{"l":"ἀναλαμβάνω","o":13,"ar":"<f><o>ἀνα-λαμβάνω</o>،</f> <s n=\"1.\"><b>يرفع (إلى فوق)</b>، <b>يُصعِد</b>: <r v=\"Mark.16.19\"></r>، <r v=\"Acts.1.2\"></r>، <r v=\"Acts.1.11\"></r> <r v=\"Acts.1.22\"></r> <r v=\"Acts.10.16\"></r>، <r v=\"1Tim.3.16\"></r>. </s> <s n=\"2.\"><b>يحمل</b>، <b>يأخذ لنفسه (يأخذ معه)</b>: <r v=\"Acts.7.43\"></r> <r v=\"Acts.20.13\"></r>، <r v=\"Acts.20.14\"></r> <r v=\"Acts.23.31\"></r>، <r v=\"Eph.6.13\"></r>، <r v=\"Eph.6.16\"></r>، <r v=\"2Tim.4.11\"></r>.†</s>","en":"<f><o>ἀνα-λαμβάνω</o>,</f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H5375\">נשׂא</h>, also for <h n=\"H3947\">לקח</h>, etc.;]</e> </et> <s n=\"1.\"><b>to take up</b>, <b>raise</b>: <r v=\"Mark.16.19\"></r>, <r v=\"Acts.1.2\"></r>, <r v=\"Acts.1.11\"></r> <r v=\"Acts.1.22\"></r> <r v=\"Acts.10.16\"></r>, <r v=\"1Tim.3.16\"></r>. </s> <s n=\"2.\"><b>to take up</b>, <b>take to oneself</b>: <r v=\"Acts.7.43\"></r> <r v=\"Acts.20.13\"></r>, <r v=\"Acts.20.14\"></r> <r v=\"Acts.23.31\"></r>, <r v=\"Eph.6.13\"></r>, <r v=\"Eph.6.16\"></r>, <r v=\"2Tim.4.11\"></r> (for late exx., v MM, <i>VGT</i>, s.v.).†</s>"},"G346":{"l":"ἀνακεφαλαιόω","o":null,"ar":"<f>** <o>ἀνα-κεφαλαιόω</o>، <g>ῶ</g></f> <s><b>يُجمِل</b>، <b>يجمع (معًا)</b>، أي يقدّم الشيء ككلٍّ واحد: الصيغة الوسطى، <r v=\"Rom.13.9\"></r>، <r v=\"Eph.1.10\"></r>.†</s>","en":"<f>** <o>ἀνα-κεφαλαιόω</o>, <g>ῶ</g></f> <et> <e t=\"derivation\">(v.s. <x><g>κεφαλαιόω</g></x>),</e> <e t=\"septuagint\">[in Th., Al.: <r v=\"Ps.72.20\"></r>*;]</e> </et> <s><b>to sum up</b>, <b>gather up</b>, present as a whole: mid., <r v=\"Rom.13.9\"></r>, <r v=\"Eph.1.10\"></r> (on WH. v. Lft., <i>Notes</i>, 321 L; AR, in l.; Cremer, 354, 748).†</s>"},"G390":{"l":"ἀναστρέφω","o":9,"ar":"<f><o>ἀνα-στρέφω</o>،</f> <s> <s n=\"1.\"><b>يقلب</b>: <r v=\"John.2.15\"></r>.</s> <s n=\"2.\"><b>يرجع</b>، <b>يعود</b>: <r v=\"Acts.5.22\"></r> <r v=\"Acts.15.16\"></r>.</s> <s n=\"3.\"><b>يتقلّب هنا وهناك</b>؛ المبني للمجهول، <b>يتردّد</b>، <b>يتغرّب (يقيم)</b>، <b>يسكن</b>: <r v=\"Matt.17.22\"></r>؛ مجازيًا (كالعبرية <h n=\"H1980\">הלךְ</h>، عند كُتّاب <g>κοινή</g> وفي <g>π.</g>)، <b>يتصرّف</b>، <b>يسلك</b>، <b>يعيش</b>: <r v=\"2Cor.1.12\"></r>، <r v=\"Eph.2.3\"></r>، <r v=\"1Tim.3.15\"></r>، <r v=\"Heb.10.33\"></r> <r v=\"Heb.13.18\"></r>، <r v=\"1Pet.1.17\"></r>، <r v=\"2Pet.2.18\"></r>.†</s> </s>","en":"<f><o>ἀνα-στρέφω</o>,</f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H7725\">שׁוּב</h>;]</e> </et> <s> <s n=\"1.\"><b>to overturn</b>: <r v=\"John.2.15\"></r>.</s> <s n=\"2.\"><b>to turn back</b>, <b>return</b>: <r v=\"Acts.5.22\"></r> <r v=\"Acts.15.16\"></r>.</s> <s n=\"3.\"><b>to turn hither and thither</b>; pass., <b>to turn oneself about</b>, <b>sojourn</b>, <b>dwell</b>: <r v=\"Matt.17.22\"></r> Rec.; metaph. (like Heb. <h n=\"H1980\">הלךְ</h>, in <g>κοινή</g> writers and in <g>π.</g>; v. Deiss., <i>LAE</i>, 315; <i>BS</i>, 88, 194; MM, <i>VGT</i>, s.v.), <b>to conduct oneself</b>, <b>behave</b>, <b>live</b>: <r v=\"2Cor.1.12\"></r>, <r v=\"Eph.2.3\"></r>, <r v=\"1Tim.3.15\"></r>, <r v=\"Heb.10.33\"></r> <r v=\"Heb.13.18\"></r>, <r v=\"1Pet.1.17\"></r>, <r v=\"2Pet.2.18\"></r>.†</s> </s> <sy><i>SYN.</i>: <x><g>περιπατέω</g></x> (Hellenistic), <x><g>πολιτεύω</g></x>.</sy>"},"G314":{"l":"ἀναγινώσκω","o":32,"ar":"<f><o>ἀνα-γινώσκω</o></f> <s n=\"1.\"><b>يعرف يقينًا</b>، <b>يعرف ثانيةً</b>، <b>يتعرّف على</b>.</s> <s n=\"2.\">عن الحروف المكتوبة، <b>يقرأ</b>: <r v=\"Matt.24.15\"></r>، <r v=\"Mark.13.14\"></r>، <r v=\"Acts.15.31\"></r> <r v=\"Acts.23.34\"></r>، <r v=\"Eph.3.4\"></r>؛ مع المنصوب للشيء، <r v=\"Matt.22.31\"></r>، <r v=\"Mark.12.10\"></r> <r v=\"Luke.6.3\"></r>، <r v=\"John.19.20\"></r>، <r v=\"Acts.8.30\"></r>، <r v=\"Acts.8.32\"></r>، <r v=\"2Cor.1.13\"></r>، <r v=\"Rev.1.3\"></r>؛ مع المنصوب للشخص، <g>Ἠσαίαν τ. προφήτην</g>، <r v=\"Acts.8.28\"></r>، <r v=\"Acts.8.30\"></r>؛ يليه <g>ἐν</g>، <r v=\"Matt.12.5\"></r> <r v=\"Matt.21.42\"></r>، <r v=\"Mark.12.26\"></r> (أي <g>ἐν τ. νόμῳ</g>)، <r v=\"Luke.10.26\"></r>؛ يليه <g>ὅτι</g>، <r v=\"Matt.19.4\"></r> <r v=\"Matt.21.16\"></r>؛ <g>τί ἐποίησε</g>، <r v=\"Matt.12.3\"></r>، <r v=\"Mark.2.25\"></r>؛ المبني للمجهول <r v=\"2Cor.3.2\"></r>؛ عن القراءة بصوت عالٍ، <r v=\"Luke.4.16\"></r>، <r v=\"Acts.13.27\"></r> <r v=\"Acts.15.21\"></r>، <r v=\"2Cor.3.15\"></r>، <r v=\"Col.4.16\"></r>، <r v=\"1Thess.5.27\"></r> .†</s>","en":"<f><o>ἀνα-γινώσκω</o></f> <et> <e t=\"derivation\">(Attic <g>ἀναγιγν-</g>),</e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H7121\">קרא</h>;]</e> </et> <s n=\"1.\"><b>to know certainly</b>, <b>know again</b>, <b>recognize</b>.</s> <s n=\"2.\">Of written characters, <b>to read</b>: <r v=\"Matt.24.15\"></r>, <r v=\"Mark.13.14\"></r>, <r v=\"Acts.15.31\"></r> <r v=\"Acts.23.34\"></r>, <r v=\"Eph.3.4\"></r>; c. acc rei, <r v=\"Matt.22.31\"></r>, <r v=\"Mark.12.10\"></r> <r v=\"Luke.6.3\"></r>, <r v=\"John.19.20\"></r>, <r v=\"Acts.8.30\"></r>, <r v=\"Acts.8.32\"></r>, <r v=\"2Cor.1.13\"></r>, <r v=\"Rev.1.3\"></r>; c. acc pers., <g>Ἠσαίαν τ. προφήτην</g>, <r v=\"Acts.8.28\"></r>, <r v=\"Acts.8.30\"></r>; seq. <g>ἐν</g>, <r v=\"Matt.12.5\"></r> <r v=\"Matt.21.42\"></r>, <r v=\"Mark.12.26\"></r> (so. <g>ἐν τ. νόμῳ</g>), <r v=\"Luke.10.26\"></r>; seq. <g>ὅτι</g>, <r v=\"Matt.19.4\"></r> <r v=\"Matt.21.16\"></r>; <g>τί ἐποίησε</g>, <r v=\"Matt.12.3\"></r>, <r v=\"Mark.2.25\"></r>; pass. <r v=\"2Cor.3.2\"></r>; of reading aloud (MM, <i>VGT</i>, s.v.), <r v=\"Luke.4.16\"></r>, <r v=\"Acts.13.27\"></r> <r v=\"Acts.15.21\"></r>, <r v=\"2Cor.3.15\"></r>, <r v=\"Col.4.16\"></r>, <r v=\"1Thess.5.27\"></r> (M, <i>Th.</i>, in l.).†</s>"},"G365":{"l":"ἀνανεόω","o":1,"ar":"<f><o>ἀνα-νεόω</o>، <g>-ῶ</g></f> <s><b>يجدّد</b>: المبني للمجهول، <r v=\"Eph.4.23\"></r> †</s>","en":"<f><o>ἀνα-νεόω</o>, <g>-ῶ</g></f> <et> <e t=\"derivation\">(&lt; <x><g>νέος</g></x>),</e> <e t=\"septuagint\">[in LXX: <r v=\"Job.33.24\"></r>, <r v=\"Ezra.3.13\"></r>, I, IV Mac<i>8</i>*;]</e> </et> <s><b>to renew</b>: pass., <r v=\"Eph.4.23\"></r> (v. Cremer, 428; MM, <i>VGT</i>, s.v.)†</s>"},"G326":{"l":"ἀναζάω","o":2,"ar":"<f>**† <o>ἀνα-ζάω</o>، <g>-ῶ</g>،</f> <s><b>يحيا ثانيةً</b>، <b>يستعيد الحياة</b>: مجازيًا عن النهضة الأخلاقية، <r v=\"Luke.15.24\"></r>؛ عن الخطية، <r v=\"Rom.7.9\"></r>.†</s>","en":"<f>**† <o>ἀνα-ζάω</o>, <g>-ῶ</g>,</f> <et> <e t=\"septuagint\">[in Al.: <r v=\"Gen.45.27\"></r>*;]</e> </et> <s><b>to live again</b>, <b>regain life</b> (cf. cl. <g>ἀναβιόω</g>; Cremer, 722; and for other exx., v MM, <i>VGT</i>, s.v.): metaph. of moral revival, <r v=\"Luke.15.24\"></r> (WH, mg., <g>ἔζησεν</g>); of sin, <r v=\"Rom.7.9\"></r>.†</s>"},"G379":{"l":"ἀναπολόγητος","o":2,"ar":"<f>*† <o>ἀναπολόγητος</o>، <g>-ον</g></f> <s><b>بلا عذر</b>، <b>لا عذر له</b> (مصطلح قضائي): <r v=\"Rom.1.20\"></r> <r v=\"Rom.2.1\"></r>.†</s>","en":"<f>*† <o>ἀναπολόγητος</o>, <g>-ον</g></f> <et> <e t=\"derivation\">(&lt; <x><g>ἀπολογεόμαι</g></x>),</e> </et> <s><b>without excuse</b>, <b>inexcusable</b> (in Polyb., al., as a forensic term; v. Lft., <i>Notes</i>, 252): <r v=\"Rom.1.20\"></r> <r v=\"Rom.2.1\"></r>.†</s>"},"G315":{"l":"ἀναγκάζω","o":9,"ar":"<f><o>ἀναγκάζω</o></f> <s><b>يضطرّ</b>، <b>يُلزم بالقوة</b> أو<b> بالإقناع، يُرغم</b>: مع المنصوب، <r v=\"2Cor.12.11\"></r>؛ وكذلك مع المصدر، <r v=\"Matt.14.22\"></r>، <r v=\"Mark.6.45\"></r>، <r v=\"Luke.14.23\"></r>، <r v=\"Acts.26.11\"></r>، <r v=\"Gal.2.14\"></r>، <r v=\"Gal.6.12\"></r>؛ المبني للمجهول مع المصدر، <r v=\"Acts.28.19\"></r>، <r v=\"Gal.2.3\"></r>.†</s>","en":"<f><o>ἀναγκάζω</o></f> <et> <e t=\"derivation\">(&lt; <x><g>ἀνάγκη</g></x>),</e> <e t=\"septuagint\">[in LXX: <r v=\"Prov.6.7\"></r> (<h n=\"H7860\">שֹׁטֵר</h>), <r v=\"1Esd.3.24\"></r>, <r v=\"1Macc.2.25\"></r>, al.;]</e> </et> <s><b>to necessitate</b>, <b>compel by force</b> or<b> persuasion, constrain</b>: c. acc., <r v=\"2Cor.12.11\"></r>; id. c. inf., <r v=\"Matt.14.22\"></r>, <r v=\"Mark.6.45\"></r>, <r v=\"Luke.14.23\"></r>, <r v=\"Acts.26.11\"></r> (on the impf. here, v. Field, <i>Notes</i>, 141; M, <i>Pr.</i>, 128 f., 247), <r v=\"Gal.2.14\"></r> <r v=\"Gal.6.12\"></r>; pass., C. inf., <r v=\"Acts.28.19\"></r>, <r v=\"Gal.2.3\"></r> (for exx., v. MM, <i>VGT</i>, s.v.).†</s>"},"G303":{"l":"ἀνά","o":13,"ar":"<f><o>ἀνά </o></f> حرف جر (وهو الأندر في العهد الجديد)، أصلاً <s><b>إلى فوق</b>، <b>صعودًا</b>، ودائمًا مع المنصوب. <s n=\"1.\">في عبارات: <g>ἀ. μέσον</g>، <b>بين</b>، <b>في وسط</b>، مع المضاف إليه، <r v=\"Matt.13.25\"></r>، <r v=\"Mark.7.31\"></r>، <r v=\"1Cor.6.5\"></r>، <r v=\"Rev.7.17\"></r> [وهكذا في السبعينية ترجمةً لـ <h n=\"H8432\">בְּתוֹךְ</h>]؛ <g>ἀ. μέρος</g>، <b>بالتناوب، واحدًا بعد الآخر</b>، <r v=\"1Cor.14.27\"></r>. </s> <s n=\"2.\">للتوزيع: <b>لكل واحد، كلٌّ منهم</b>: <r v=\"Matt.20.9-Matt.20.10\"></r>، <r v=\"Luke.9.3\"></r>، <r v=\"Luke.9.14\"></r> <r v=\"Luke.10.1\"></r>، <r v=\"John.2.6\"></r>، <r v=\"Rev.4.8\"></r>. </s> <s n=\"3.\">ظرفيًّا (استعمال عامّي)، <g>ἀ. εἷς ἕκαστος</g>، <r v=\"Rev.21.21\"></r>.</s> <s>وفي التركيب سابقةً، تدل <g>ἀ.</g> على <s n=\"(a)\"><b>إلى فوق</b>: <g>ἀναβαίνειν</g>؛ </s> <s n=\"(b)\"><b>إلى</b>: <g>ἀναγγέλλειν</g>؛ </s> <s n=\"(c)\"><b>من جديد</b>: <g>ἀναγεννᾶν</g>؛ </s> <s n=\"(d)\"><b>رجوعًا</b>: <g>ἀνακάμπτειν.</g>†</s> </s> </s>","en":"<f><o>ἀνά </o></f> prep. (the rarest in NT; M, <i>Pr.</i>, 98; MM, <i>VGT</i>, s.v.), prop., <s><b>upwards</b>, <b>up</b>, always c. acc. <s n=\"1.\">In phrases: <g>ἀ. μέσον</g>, <b>among</b>, <b>between</b>, c. gen., <r v=\"Matt.13.25\"></r>, <r v=\"Mark.7.31\"></r>, <r v=\"1Cor.6.5\"></r> (M, <i>Pr.</i>, 99), <r v=\"Rev.7.17\"></r> [so in LXX for <h n=\"H8432\">בְּתוֹךְ</h>]; <g>ἀ. μέρος</g>, <b>in turn</b>, <r v=\"1Cor.14.27\"></r> (both found in Polyb.; cf. M<i>Gr.</i> <g>ἀνάμεσα</g>). </s> <s n=\"2.\">Distrib., <b>apiece, by</b>: <r v=\"Matt.20.9-Matt.20.10\"></r>, <r v=\"Luke.9.3\"></r> (WH om.), <r v=\"Luke.9.14\"></r> <r v=\"Luke.10.1\"></r>, <r v=\"John.2.6\"></r>, <r v=\"Rev.4.8\"></r>. </s> <s n=\"3.\">Adverbially (\"a vulgarism,\" Bl., § 51, 5; cf. Deiss., BS, 139 f.), <g>ἀ. εἷς ἕκαστος</g>, <r v=\"Rev.21.21\"></r>.</s> <s>As prefix, <g>ἀ.</g> signifies <s n=\"(a)\"><b>up</b>: <g>ἀναβαίνειν</g>; </s> <s n=\"(b)\"><b>to</b>: <g>ἀναγγέλλειν</g>; </s> <s n=\"(c)\"><b>anew</b>: <g>ἀναγεννᾶν</g>; </s> <s n=\"(d)\"><b>back</b>: <g>ἀνακάμπτειν.</g>†</s> </s> </s>"},"G370":{"l":"ἀνάξιος","o":1,"ar":"<f><o>ἀν-άξιος</o>، <g>-ον</g></f> <s><b>غير مستحق</b>، <b>غير أهل لـ</b>: مع المضاف إليه، <r v=\"1Cor.6.2\"></r>.†</s>","en":"<f><o>ἀν-άξιος</o>, <g>-ον</g></f> <et> <e t=\"derivation\">(<g>ἀ-</g> neg., <x><g>ἄξιος</g></x>),</e> <e t=\"septuagint\">[in LXX: <r v=\"Jer.15.19\"></r> <h>א</h>2 (<h n=\"H2151\">זלל</h>), <r v=\"Ezra.8.13\"></r>, <r v=\"Sir.25.8\"></r>*;]</e> </et> <s><b>unworthy</b>: c. gen., <r v=\"1Cor.6.2\"></r> (MM, <i>VGT</i>, s.v.).†</s>"},"G329":{"l":"ἀναζωπυργέω","o":1,"ar":"<f>** <o>ἀνα-ζωπυργέω</o>، <g>-ῶ</g></f> <s><b>أضرم من جديد</b>: مجازيًا: <r v=\"2Tim.1.6\"></r>.†</s>","en":"<f>** <o>ἀνα-ζωπυργέω</o>, <g>-ῶ</g></f> <et> <e t=\"derivation\">(&lt; <x><g>ζωός</g></x>, <x><g>πῦρ</g></x>),</e> <e t=\"septuagint\">[in LXX: <r v=\"1Macc.13.7\"></r>*;]</e> </et> <s><b>to kindle afresh</b>: metaph., <r v=\"2Tim.1.6\"></r> (for vernac. exx., v. MM, <i>VGT</i>, s.v.).†</s>"},"G362":{"l":"ἀναμένω","o":1,"ar":"<f><o>ἀνα-μένω </o></f> <s><b>انتظر، ترقّب</b> «مَن يُتوقّع مجيئه، وربما مع فكرة الصبر والثقة»، مع المنصوب، <r v=\"1Thess.1.10\"></r>.†</s>","en":"<f><o>ἀνα-μένω </o></f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H6960\">קוה</h> pi.;]</e> </et> <s><b>to await</b> \"one whose coming is expected, perhaps with the added idea of patience and confidence\" c. acc., <r v=\"1Thess.1.10\"></r> (v. M, <i>Th.</i>, in l.; MM, <i>VGT</i>, s.v.).†</s>"},"G321":{"l":"ἀνάγω","o":23,"ar":"<f><o>ἀν-άγω </o></f> <s><b>قاد</b> أو <b>أصعد</b>: يليه <g>είς</g> مع المنصوب للمكان، <r v=\"Matt.4.1\"></r>، <r v=\"Luke.2.22\"></r> <r v=\"Luke.4.5\"></r>، <r v=\"Acts.9.39\"></r> <r v=\"Acts.16.34\"></r>؛ عن إقامة الموتى، <g>ἐκ νεκρῶν</g>، <r v=\"Rom.10.7\"></r>، <r v=\"Heb.13.20\"></r>؛ <b>أخرج وقدّم أمام</b>، <g>τ. λαῷ</g>، <r v=\"Acts.12.4\"></r>؛ بالمعنى الذبائحي، <b>قدّم، أصعد</b>، <g>θυσίαν</g>، <r v=\"Acts.7.41\"></r>. الصيغة الوسطى، بالمعنى البحري: <b>أقلع، أبحر</b>: <r v=\"Luke.8.22\"></r>، <r v=\"Acts.13.13\"></r> <r v=\"Acts.16.11\"></r> <r v=\"Acts.18.21\"></r> <r v=\"Acts.20.3\"></r>، <r v=\"Acts.20.13\"></r> <r v=\"Acts.21.1\"></r>، <r v=\"Acts.21.2\"></r> <r v=\"Acts.27.2\"></r>، <r v=\"Acts.27.4\"></r> <r v=\"Acts.27.12\"></r>، <r v=\"Acts.27.21\"></r> <r v=\"Acts.28.10\"></r>، <r v=\"Acts.28.10\"></r> (قارن <g>ἐπ-ανάγω</g>).†</s>","en":"<f><o>ἀν-άγω </o></f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H5927\">עָלָה</h> hi.;]</e> </et> <s><b>to lead</b> or <b>bring up</b>: seq. <g>είς</g>, c. acc. loc., <r v=\"Matt.4.1\"></r>, <r v=\"Luke.2.22\"></r> <r v=\"Luke.4.5\"></r> (WH om. <g>είς</g>, <g>κ.τ.λ.</g>), <r v=\"Acts.9.39\"></r> <r v=\"Acts.16.34\"></r>; of raising the dead (cl.), <g>ἐκ νεκρῶν</g>, <r v=\"Rom.10.7\"></r>, <r v=\"Heb.13.20\"></r>; <b>to produce and set before</b>, <g>τ. λαῷ</g>, <r v=\"Acts.12.4\"></r> (MM, <i>VGT</i>, s.v.); in sacrificial sense (MM, <i>VGT</i>, s.v.), <b>to offer</b>, <g>θυσίαν</g>, <r v=\"Acts.7.41\"></r>. Mid., in nautical sense (Hom., Hdt., Thuc., al.), <b>to put to sea</b>: <r v=\"Luke.8.22\"></r>, <r v=\"Acts.13.13\"></r> <r v=\"Acts.16.11\"></r> <r v=\"Acts.18.21\"></r> <r v=\"Acts.20.3\"></r>, <r v=\"Acts.20.13\"></r> <r v=\"Acts.21.1\"></r>, <r v=\"Acts.21.2\"></r> <r v=\"Acts.27.2\"></r>, <r v=\"Acts.27.4\"></r> <r v=\"Acts.27.12\"></r>, <r v=\"Acts.27.21\"></r> <r v=\"Acts.28.10\"></r>, <r v=\"Acts.28.10\"></r> (cf. <g>ἐπ-ανάγω</g>).†</s>"},"G342":{"l":"ἀνακαίνωσις","o":2,"ar":"<f>† <o>ἀνακαίνωσις</o>، <g>-εως, ἡ</g></f> <s><b>تجديد</b>: <r v=\"Rom.12.2\"></r>، <r v=\"Titus.3.5\"></r>.†</s>","en":"<f>† <o>ἀνακαίνωσις</o>, <g>-εως, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <x><g>ἀνακαινόω</g></x>),</e> </et> <s><b>renewal</b>: <r v=\"Rom.12.2\"></r>, <r v=\"Titus.3.5\"></r> (Cremer, 324; MM, <i>VGT</i>, s.v.).†</s> <sy><i>SYN.</i>: <x><g>παλινγενεσία</g></x>, in NT, <i>new birth</i>, of which <g>ἀ.</g> is the consequent renewal or renovation, in which man as well as God takes part (v. Tr., <i>Syn.</i>, § xviii) </sy>"},"G330":{"l":"ἀναθάλλω","o":1,"ar":"<f><o>ἀνα-θάλλω</o></f> <s><b>أنعش، جدّد (أزهر ثانيةً)</b>: <r v=\"Phil.4.10\"></r>.†</s>","en":"<f><o>ἀνα-θάλλω</o></f> <et> <e t=\"derivation\">(&lt; <x><g>θάλλω</g></x>, <i>to flourish</i>),</e> <e t=\"septuagint\">[in LXX: <r v=\"Ps.28.7\"></r> (<h n=\"H5937\">עלז</h>), <r v=\"Ezek.17.24\"></r> (<h n=\"H6524\">פּרח</h> hi.), <r v=\"Hos.8.9\"></r>, <r v=\"Wis.4.4\"></r>, <r v=\"Sir.5.1-Sir.5.15\"></r>*;]</e> </et> <s><b>to revive</b>: <r v=\"Phil.4.10\"></r> (of MM, <i>VGT</i>, s.v.).†</s>"},"G378":{"l":"ἀναπληρόω","o":6,"ar":"<f><o>ἀνα-πληρόω</o>، <g>-ῶ</g>،</f> <s n=\"1.\"><b>يملأ</b>، <b>يُكمل</b>: <g>τόπον</g>، <b>يشغل مكان</b> (قارن العبرية <h n=\"H4725\">מָקוֹם</h> <h n=\"H7999\">מִלֵּא</h>)، <r v=\"1Cor.14.16\"></r>؛ <g>άμαρτίας</g>، <b>يُكمل عدد (خطاياهم)</b>، <r v=\"1Thess.2.16\"></r>؛ <g>τ. νόμον</g>، <b>يتمّم (الناموس) تمامًا</b>، <r v=\"Gal.6.2\"></r>؛ المبني للمجهول، <g>προφητεία</g>، <b>تتمّ (النبوة)</b>، <r v=\"Matt.13.14\"></r>.</s> <s n=\"2.\"><b>يسدّ، يعوّض</b>: <g>τὸ ὑστέρημα</g> (النقص)، <r v=\"1Cor.16.17\"></r>، <r v=\"Phil.2.30\"></r>.†</s>","en":"<f><o>ἀνα-πληρόω</o>, <g>-ῶ</g>,</f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H4390\">מלא</h>, <r v=\"Lev.12.6\"></r>, al.; also <h n=\"H7999\">שׁלם</h> (<r v=\"Gen.15.16\"></r>, <r v=\"1Kgs.7.51\"></r>, <r v=\"Isa.60.20\"></r>), etc.;]</e> </et> <s n=\"1.\"><b>to fill up</b>, <b>make full</b> (in <g>π.</g> of completing contracts and making up rent; cf. MM, <i>VGT</i>, s.v.): <g>τόπον</g>, <b>take one's place</b> (cf. Heb. <h n=\"H4725\">מָקוֹם</h> <h n=\"H7999\">מִלֵּא</h>), <r v=\"1Cor.14.16\"></r>; <g>άμαρτίας</g>, <b>complete the number</b>, <r v=\"1Thess.2.16\"></r>; <g>τ. νόμον</g>, <b>observe perfectly</b>, <r v=\"Gal.6.2\"></r>; pass., <g>προφητεία</g>, <b>fulfilled</b>, <r v=\"Matt.13.14\"></r>.</s> <s n=\"2.\"><b>to supply</b>: <g>τὸ ὑστέρημα</g>, <r v=\"1Cor.16.17\"></r>, <r v=\"Phil.2.30\"></r> (Cremer, 838).†</s>"},"G316":{"l":"ἀναγκαῖος","o":8,"ar":"<f>** <o>ἀναγκαῖος</o>، <g>-αῖα, -αῖον</g></f> <s n=\"1.\"><b>ضروري، لازم</b>: <r v=\"Acts.13.46\"></r>، <r v=\"1Cor.12.22\"></r>، <r v=\"2Cor.9.5\"></r>، <r v=\"Phil.2.25\"></r>، <r v=\"Titus.3.14\"></r>، <r v=\"Heb.8.3\"></r>؛ صيغة التفضيل <g>-αιότερον</g> (ألزم)، <r v=\"Phil.1.24\"></r>.</s> <s n=\"2.\">عن الأشخاص المرتبطين بروابط القرابة أو الصداقة: <b>قريب</b>، <b>حميم</b>: <g>ἀ. φίλοι</g> (الأصدقاء الأقربون)، <r v=\"Acts.10.24\"></r>.†</s>","en":"<f>** <o>ἀναγκαῖος</o>, <g>-αῖα, -αῖον</g></f> <et> <e t=\"derivation\">(&lt; <x><g>ἀνάγκη</g></x>),</e> <e t=\"septuagint\">[in LXX: <r v=\"Ezra.8.13\"></r>, <r v=\"Wis.16.3\"></r>, <r v=\"Sir.0.22\"></r>, <r v=\"2Macc.4.23\"></r> <r v=\"2Macc.9.21\"></r>, <r v=\"4Macc.1.2\"></r>*;]</e> </et> <s n=\"1.\"><b>necessary</b>: <r v=\"Acts.13.46\"></r>, <r v=\"1Cor.12.22\"></r>, <r v=\"2Cor.9.5\"></r>, <r v=\"Phil.2.25\"></r>, <r v=\"Titus.3.14\"></r>, <r v=\"Heb.8.3\"></r>; comp. <g>-αιότερον</g>, <r v=\"Phil.1.24\"></r>.</s> <s n=\"2.\">Of persons connected by bonds of nature or friendship, <b>near</b>, <b>intimate</b> (Field, <i>Notes</i>, 118; <g>ΜΜ</g>, <i>VGT</i>, s.v.): <g>ἀ. φίλοι</g>, <r v=\"Acts.10.24\"></r>.†</s>"},"G363":{"l":"ἀναμιμνήσκω","o":6,"ar":"<f><o>ἀνα-μιμνήσκω</o></f> <s><b>يذكّر</b>، <b>يستحضر في ذاكرة غيره</b>: مع المنصوب للشيء، <r v=\"1Cor.4.17\"></r>؛ مع المصدر، <r v=\"2Tim.1.6\"></r>. في المبني للمجهول: <b>يتذكّر</b>، <b>يستحضر في ذهنه</b>: <r v=\"Mark.11.21\"></r>، <r v=\"Mark.14.72\"></r>، <r v=\"2Cor.7.15\"></r>، <r v=\"Heb.10.32\"></r>.†</s>","en":"<f><o>ἀνα-μιμνήσκω</o></f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H2142\">זכר</h> hi.;]</e> </et> <s><b>to remind</b>, <b>call to one's remembrance</b>: c. acc. rei, <r v=\"1Cor.4.17\"></r>; c. inf., <r v=\"2Tim.1.6\"></r>. Pass., <b>to remember</b>, <b>call to mind</b>: <r v=\"Mark.11.21\"></r> <r v=\"Mark.14.72\"></r>, <r v=\"2Cor.7.15\"></r>, <r v=\"Heb.10.32\"></r>.†</s>"},"G396":{"l":"ἀνατρέπω","o":3,"ar":"<f><o>ἀνα-τρέπω</o>،</f> <s><b>يقلب</b>، <b>يهدم</b>: <r v=\"John.2.15\"></r>؛ مجازيًا: <b>يقلب (يُفسد)</b>: <r v=\"2Tim.2.18\"></r>، <r v=\"Titus.1.11\"></r>.†</s>","en":"<f><o>ἀνα-τρέπω</o>,</f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H1760\">דּחה</h>, <h n=\"H1920\">הדף</h>, etc.;]</e> </et> <s><b>to overturn</b>, <b>destroy</b>: <r v=\"John.2.15\"></r> WH, txt.; metaph., <b>to subvert</b> (MM, <i>VGT</i>, s.v.): <r v=\"2Tim.2.18\"></r>, <r v=\"Titus.1.11\"></r>.†</s>"},"G360":{"l":"ἀναλύω","o":2,"ar":"<f>** <o>ἀνα-λύω</o></f> <s n=\"1.\"><b>يحلّ، يفكّ</b>.</s> <s n=\"2.\"><b>يحلّ (المرساة) للرحيل</b>، <b>ينطلق، يرحل</b>: من الحياة، <r v=\"Phil.1.23\"></r> </s> <s n=\"3.\"><b>يرجع</b>، <r v=\"Luke.12.36\"></r>.†</s>","en":"<f>** <o>ἀνα-λύω</o></f> <et> <e t=\"septuagint\">[in LXX: <r v=\"1Esd.3.3\"></r>, <r v=\"Tob.2.9\"></r>, <r v=\"Jdt.13.1\"></r>, <r v=\"Sir.3.15\"></r>, Wi<i>3</i>, Mac<i>10</i>*;]</e> </et> <s n=\"1.\"><b>to unloose</b>.</s> <s n=\"2.\"><b>to unloose for departure</b>, <b>depart</b> (MM, <i>VGT</i>, s.v.): from life, <r v=\"Phil.1.23\"></r> </s> <s n=\"3.\"><b>to return</b>, <r v=\"Luke.12.36\"></r>.†</s>"},"G356":{"l":"ἀναλογία","o":1,"ar":"<f>** <o>ἀναλογία</o>، <g>-ας, ἡ</g></f> <s><b>نسبة، مقدار</b>: <r v=\"Rom.12.6\"></r>.†</s>","en":"<f>** <o>ἀναλογία</o>, <g>-ας, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <x><g>λόγος</g></x>),</e> <e t=\"septuagint\">[in Al.: <r v=\"Lev.27.18\"></r>*;]</e> </et> <s><b>proportion</b> (MM, <i>VGT</i>, s.v.): <r v=\"Rom.12.6\"></r> (cf. Cremer, 397).†</s>"},"G364":{"l":"ἀνάμνησις","o":4,"ar":"<f><o>ἀνάμνησις</o>، <g>-εως, ἡ</g></f> <s><b>ذِكْر، تذكار</b>: <g>εἰς τ. ἐμὴν ἀ.</g>: <r v=\"Luke.22.19\"></r>، <r v=\"1Cor.11.24\"></r>، <r v=\"1Cor.11.25\"></r>؛ <g>ἀ. ἁμαρτιῶν</g>: <r v=\"Heb.10.3\"></r>.†</s>","en":"<f><o>ἀνάμνησις</o>, <g>-εως, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <x><g>ἀναμιμνήσκω</g></x>), </e> <e t=\"septuagint\">[in LXX: Ps 37 (38), 69 (70) tit. (<h n=\"H2142\">זכר</h> hi.), <r v=\"Lev.24.7\"></r> (<h n=\"H234\">אַזְכָּרָה</h>), <r v=\"Num.10.10\"></r> (<h n=\"H2146\">זִכְרוֹן</h>), <r v=\"Wis.16.6\"></r>*;] </e> </et> <s><b>remembrance</b>: <g>εἰς τ. ἐμὴν ἀ.</g>, <r v=\"Luke.22.19\"></r> (WH om.), <r v=\"1Cor.11.24\"></r>, <r v=\"1Cor.11.25\"></r>; <g>ἀ. ἁμαρτιῶν</g>, <r v=\"Heb.10.3\"></r> (v. Abbott, <i>Essays</i>, 122 ff.; <i>DCG</i>, ii, 74<i>a</i>).†</s> <sy><i>SYN.</i>: <x><g>ὑπόμνησις</g></x> (v. Tr., <i>Syn.</i>, § cvii). </sy>"},"G394":{"l":"ἀνατίθημι","o":2,"ar":"<f><o>ἀνα-τίθημι</o>،</f> <s><b>وضع على</b>، <b>رفع</b>، إلخ. الصيغة الوسطى <g>-εμαι</g>، عند الكتّاب المتأخرين: <b>عرض</b>، <b>أعلن</b>: <r v=\"Acts.25.14\"></r>، <r v=\"Gal.2.2\"></r>.†</s>","en":"<f><o>ἀνα-τίθημι</o>,</f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H2763\">חרם</h> (Cremer, 546);]</e> </et> <s><b>to lay upon</b>, <b>set up</b>, etc. Mid. <g>-εμαι</g>, in late writers (Plut., al.; v. also MM, <i>VGT</i>, s.v.), <b>to set forth</b>, <b>declare</b>: <r v=\"Acts.25.14\"></r>, <r v=\"Gal.2.2\"></r>.†</s>"},"G355":{"l":"ἀναλίσκω","o":2,"ar":"<f><o>ἀν-αλίσκω</o></f> <s n=\"1.\"><b>أنفق</b>.</s> <s n=\"2.\"><b>أفنى، أهلك</b>: <r v=\"Luke.9.54\"></r>، <r v=\"Gal.5.15\"></r>، <r v=\"2Thess.2.8\"></r>.†</s>","en":"<f><o>ἀν-αλίσκω</o></f> <et> <e t=\"derivation\">(on the etymology, v. MM, <i>VGT</i>, s.v.),</e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H398\">אכל</h> also for <h n=\"H3615\">כּלה</h>, etc.;]</e> </et> <s n=\"1.\"><b>to expend</b>.</s> <s n=\"2.\"><b>to consume, destroy</b>: <r v=\"Luke.9.54\"></r>, <r v=\"Gal.5.15\"></r>, <r v=\"2Thess.2.8\"></r>, Rec. WH, mg.†</s>"},"G341":{"l":"ἀνακαινόω","o":2,"ar":"<f><o>ἀνα-καινόω</o>، <g>-ῶ</g></f> <s><b>جدّد</b>: <r v=\"2Cor.4.16\"></r>، <r v=\"Col.3.10\"></r>.†</s>","en":"<f><o>ἀνα-καινόω</o>, <g>-ῶ</g></f> <et> <e t=\"derivation\">= <x><g>ἀνακαινίζω</g></x> (cf. MM, <i>VGT</i>, s.v.),</e> </et> <s><b>to make new</b>: <r v=\"2Cor.4.16\"></r>, <r v=\"Col.3.10\"></r> (v. Cremer, 323).†</s>"},"G371":{"l":"ἀναξίως","o":1,"ar":"<f>** <o>ἀναξίως</o></f> (انظر أعلاه)، ظرف، <s><b>بدون استحقاق</b>: <r v=\"1Cor.11.27\"></r>.†</s>","en":"<f>** <o>ἀναξίως</o></f> (v. supr.), adv., <et> <e t=\"septuagint\">[in LXX: <r v=\"2Macc.14.42\"></r>*;]</e> </et> <s><b>in an unworthy manner</b>: <r v=\"1Cor.11.27\"></r>.†</s>"},"G302":{"l":"ἄν_1","o":716,"ar":"<f><o>ἄν</o>، </f> أداة شرطية، <s>لا يمكن عادةً ترجمتها منفردة، إذ تتوقف قوتها على التراكيب التي ترد فيها. <s n=\"1.\">في جواب الشرط، <s n=\"(i)\">مع الإخباري في الماضي الناقص أو الماضي البسيط، للتعبير عمّا كان سيحدث أو كان قد حدث لو (<g>εἰ</g> مع الماضي الناقص أو الماضي البسيط أو الماضي الأتم) تحقق شرط ما: <r v=\"Luke.7.39\"></r> <r v=\"Luke.17.6\"></r>، <r v=\"John.5.46\"></r>، <r v=\"Gal.1.10\"></r>، <r v=\"Matt.12.7\"></r> <r v=\"Matt.24.43\"></r>، <r v=\"1Cor.2.8\"></r>، <r v=\"Acts.18.14\"></r>، <r v=\"1John.2.19\"></r>، وفي مواضع أخرى. وقد يُفهم الشرط ضمنًا: <r v=\"Matt.25.27\"></r>، <r v=\"Luke.19.23\"></r>. وفي الجمل الافتراضية التي تعبّر عن غير الواقع تُحذف <g>ἄν</g>: <r v=\"John.8.39\"></r> <r v=\"John.15.24\"></r> يوحنا 19: 11، <r v=\"Rom.7.7\"></r>، <r v=\"Gal.4.15\"></r>؛ </s> <s n=\"(ii)\">في اليونانية الكلاسيكية: مع صيغة التمني والمصدر واسم الفاعل. </s> </s> <s n=\"2.\">مع أدوات الشرط والوصل والزمان والغاية؛ <s n=\"(i)\">مع صيغة الاحتمال، <s n=\"(a)\">في الشرط مع <g>εἰ</g>، وتُدمج معها فتصير <g>ἐάν</g>، انظره؛ </s> <s n=\"(b)\">في جمل الشرط والوصل والزمان (مندمجة مع <g>ὅτε, ἐπεί</g> إلخ؛ انظر تحت مدخل <g>ὅταν, ἐπάν</g> إلخ): <b>-ما، أيًّا كان</b>؛ <s n=\"(α)\">مع المضارع، <g>ἡνίκα</g>، <r v=\"2Cor.3.15\"></r>؛ <g>ὃς ἄν</g>، <r v=\"Rom.9.15\"></r><i>(السبعينية)</i> <r v=\"Rom.16.2\"></r>، وفي مواضع أخرى؛ <g>ὅσοι ἄν</g>، <r v=\"Luke.9.5\"></r>؛ <g>ὡς ἄν</g>، <r v=\"Rom.15.24\"></r>؛ </s> <s n=\"(β)\">مع الماضي البسيط، <g>ὃς ἄν</g>، <r v=\"Matt.5.21\"></r>، <r v=\"Matt.5.22\"></r>، <r v=\"Matt.5.31\"></r>؛ <g>ἕως ἄν</g>، <b>إلى أن، حتى</b>، <r v=\"Matt.2.13\"></r>، <r v=\"Mark.6.10\"></r>، وفي مواضع أخرى؛ <g>ὡς ἄν</g>، <b>حالما، عندما</b>، <r v=\"1Cor.11.34\"></r>، <r v=\"Phil.2.23\"></r>. وعن الاستعمال الكثير لـ <g>ἐάν</g> بدل <g>ἄν</g> مع الكلمات السابقة، انظر تحت مدخل <g>ἐάν</g>؛ </s> </s> </s> <s n=\"(ii)\">في اليونانية المتأخرة، عند الحديث عن واقعة فعلية، مع الإخباري: <g>ὅταν</g> (انظره)؛ <g>ὅπου ἄν</g>، <r v=\"Mark.6.56\"></r>؛ <g>καθότι ἄν</g>، <r v=\"Acts.2.45\"></r> <r v=\"Acts.4.35\"></r>؛ <g>ὡς ἄν</g>، <r v=\"1Cor.12.2\"></r>. </s> </s> <s n=\"3.\">في التركيب التكراري، مع الإخباري في الماضي الناقص والماضي البسيط: <r v=\"Acts.2.45\"></r> <r v=\"Acts.4.35\"></r>، <r v=\"1Cor.12.2\"></r>. </s> <s n=\"4.\">مع صيغة التمني، فتعطي معنى الإمكان للسؤال أو الأمنية: <r v=\"Acts.8.31\"></r> <r v=\"Acts.26.29\"></r>. </s> <s n=\"5.\">تراكيب فيها حذف: <g>εἰ μή τι ἄν</g>، <r v=\"1Cor.7.5\"></r>؛ <g>ὡς ἄν</g> مع المصدر، <b>كأنّ، كما لو</b>، <r v=\"2Cor.10.9\"></r>. </s> </s>","en":"<f><o>ἄν</o>, </f> conditional particle, <s>which cannot usually be separately translated in English, its force depending on the constructions which contain it (see further, LS, s.v.; WM, §xlii; M, <i>Pr.</i>, 165 ff.; MM, <i>VGT</i>, s.v.). <s n=\"1.\">In apodosis, <s n=\"(i)\">c. indic, impf. or aor., expressing what would be or would have been if (<g>εἰ</g> c. impf., aor. or plpf.) some condition were or had been fulfilled: <r v=\"Luke.7.39\"></r> <r v=\"Luke.17.6\"></r>, <r v=\"John.5.46\"></r>, <r v=\"Gal.1.10\"></r>, <r v=\"Matt.12.7\"></r> <r v=\"Matt.24.43\"></r>, <r v=\"1Cor.2.8\"></r>, <r v=\"Acts.18.14\"></r>, <r v=\"1John.2.19\"></r>, al. The protasis is sometimes understood (as also in cl.): <r v=\"Matt.25.27\"></r>, <r v=\"Luke.19.23\"></r>. In hypothetical sentences, expressing unreality, <g>ἄν</g> (as often in late writers, more rarely in cl.) is omitted: <r v=\"John.8.39\"></r> <r v=\"John.15.24\"></r> 19:11, <r v=\"Rom.7.7\"></r>, <r v=\"Gal.4.15\"></r>; </s> <s n=\"(ii)\">c. opt., inf., ptcp. (cl.; v. LS, s.v.; M, <i>Int.</i>, §275; M, <i>Pr.</i>, 167:4). </s> </s> <s n=\"2.\">In combination with conditional, relative, temporal, and final words; <s n=\"(i)\">as in cl., c. subj., <s n=\"(a)\">in protasis with <g>εἰ</g>, in Attic contr. <g>ἐάν</g>, q.v.; </s> <s n=\"(b)\">in conditional, relative, and temporal clauses (coalescing with <g>ὅτε, ἐπεί</g>, etc.; v.s. <g>ὅταν, ἐπάν</g>, etc.), <b>ever, soever</b>; <s n=\"(α)\">c. pres., <g>ἡνίκα</g>, <r v=\"2Cor.3.15\"></r>; <g>ὃς ἄν</g>, <r v=\"Rom.9.15\"></r><i>(LXX)</i> <r v=\"Rom.16.2\"></r>, al.; <g>ὅσοι ἄν</g>, <r v=\"Luke.9.5\"></r>; <g>ὡς ἄν</g>, <r v=\"Rom.15.24\"></r> (M, <i>Pr.</i>, 167); </s> <s n=\"(β)\">c. aor., <g>ὃς ἄν</g>, <r v=\"Matt.5.21\"></r>, <r v=\"Matt.5.22\"></r>, <r v=\"Matt.5.31\"></r>; <g>ἕως ἄν</g>, <b>until</b>, <r v=\"Matt.2.13\"></r>, <r v=\"Mark.6.10\"></r>, al.; <g>ὡς ἄν</g>, <b>as soon as</b> (M, <i>Pr.</i>, 167), <r v=\"1Cor.11.34\"></r>, <r v=\"Phil.2.23\"></r>. On the freq. use of <g>ἐάν</g> for <g>ἄν</g> with the foregoing words, v.s. <g>ἐάν</g>; </s> </s> </s> <s n=\"(ii)\">in late Gk., when some actual fact is spoken of, c. indic.: <g>ὅταν</g> (q.v.); <g>ὅπου ἄν</g>, <r v=\"Mark.6.56\"></r> (M, <i>Pr.</i>, 168); <g>καθότι ἄν</g>, <r v=\"Acts.2.45\"></r> <r v=\"Acts.4.35\"></r>; <g>ὡς ἄν</g>, <r v=\"1Cor.12.2\"></r>. </s> </s> <s n=\"3.\">in iterative construction, c. impf. and aor. indic. (M, <i>Pr.</i>, 167): <r v=\"Acts.2.45\"></r> <r v=\"Acts.4.35\"></r>, <r v=\"1Cor.12.2\"></r>. </s> <s n=\"4.\">c. optat., giving a potential sense to a question or wish: <r v=\"Acts.8.31\"></r> <r v=\"Acts.26.29\"></r>. </s> <s n=\"5.\">Elliptical constructions: <g>εἰ μή τι ἄν</g> (M, <i>Pr.</i>, 169), <r v=\"1Cor.7.5\"></r>; <g>ὡς ἄν</g>, c. inf., <b>as it were</b> (op. cit. 167), <r v=\"2Cor.10.9\"></r>. </s> </s>"},"G320":{"l":"ἀνάγνωσις","o":3,"ar":"<f><o>ἀνά-γνωσις</o>، <g>-εως, ἡ </g></f> <s n=\"1.\">في اليونانية الكلاسيكية: <b>تعرّف، إدراك</b>. </s> <s n=\"2.\"><b>قراءة</b>: عن قراءة الكتاب المقدس علنًا: <r v=\"Acts.13.15\"></r>، <r v=\"2Cor.3.14\"></r>، <r v=\"1Tim.4.13\"></r>.†</s>","en":"<f><o>ἀνά-γνωσις</o>, <g>-εως, ἡ </g></f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Neh.8.8\"></r> (<h n=\"H4744\">מִקְרָא</h>), <r v=\"1Esd.9.48\"></r>, <r v=\"Sir.0.9\"></r>, <r v=\"Sir.0.13\"></r>*;]</e> </et> <s n=\"1.\"><b>recognition</b> (Hdt.). </s> <s n=\"2.\"><b>reading</b> (Plat., al.): of the public reading of Scripture (Milligan, <i>NTD</i>, 173, 210 f.): <r v=\"Acts.13.15\"></r>, <r v=\"2Cor.3.14\"></r>, <r v=\"1Tim.4.13\"></r> (Cremer, 158; MM, <i>VGT</i>, s.v.).†</s>"},"G387":{"l":"ἀναστατόω","o":3,"ar":"<f>† <o>ἀνα-στατόω</o>، <g>ῶ</g></f> <s><b>هيّج</b>، <b>أثار</b>، <b>أقلق</b>: مع المنصوب؛ <s n=\"(a)\">إلى الشغب والفتنة: <r v=\"Acts.17.6\"></r> <r v=\"Acts.21.38\"></r>؛</s> <s n=\"(b)\">بالتعليم الكاذب: <r v=\"Gal.5.12\"></r>.†</s> </s>","en":"<f>† <o>ἀνα-στατόω</o>, <g>ῶ</g></f> <et> <e t=\"derivation\">(&lt; <x><g>ἀνάστατος</g></x>, <i>driven from home</i>; &lt; <x><g>ἀνίστημι</g></x>),</e> <e t=\"septuagint\">[in LXX: <r v=\"Dan.7.23\"></r> (<h n=\"H1758\">דּוּשׁ</h>;* also in Aq., and in <g>π.</g> (v. Deiss., <i>LAE</i>, 80 f.; MM, <i>VGT</i>, s.v.),]</e> </et> <s><b>to stir up</b>, <b>excite</b>, <b>unsettle</b>: c. acc.; <s n=\"(a)\">to tumult and sedition: <r v=\"Acts.17.6\"></r> <r v=\"Acts.21.38\"></r>;</s> <s n=\"(b)\">by false teaching: <r v=\"Gal.5.12\"></r> (v. Milligan, <i>NTD</i>, 73 f.).†</s> </s>"},"G359":{"l":"ἀνάλυσις","o":1,"ar":"<f>* <o>ἀνά-λυσις</o>، <g>-εως, ἡ</g></f> <s><b>حلّ</b>، كحلّ السفينة من مرساها، ومن ثمّ: <b>انحلال، رحيل</b>: من الحياة، <r v=\"2Tim.4.6\"></r>.†</s>","en":"<f>* <o>ἀνά-λυσις</o>, <g>-εως, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <x><g>ἀναλύω</g></x>),</e> </et> <s><b>a loosing</b>, e.g. of a vessel from its moorings, hence, <b>departure</b>: from life, <r v=\"2Tim.4.6\"></r>.†</s>"},"G312":{"l":"ἀναγγέλλω","o":14,"ar":"<f><o>ἀν-αγγέλλω</o>،</f> <s n=\"1.\"><b>ردّ خبرًا</b>، <b>أخبر</b>: <r v=\"John.5.15\"></r>، <r v=\"Acts.14.27\"></r> <r v=\"Acts.15.4\"></r>، <r v=\"2Cor.7.7\"></r> </s> <s n=\"2.\">لاحقًا، = <x><g>ἀπαγγέλλω</g></x>: <b>أعلن، أخبر</b> (كما في السبعينية): <r v=\"Matt.28.11\"></r>، <r v=\"John.4.25\"></r> <r v=\"John.16.13-John.16.15\"></r>، <r v=\"Acts.19.18\"></r> <r v=\"Acts.20.20\"></r>، <r v=\"Acts.20.27\"></r> <r v=\"Rom.15.21\"></r>، <r v=\"1Pet.1.12\"></r>، <r v=\"1John.1.5\"></r>.†</s>","en":"<f><o>ἀν-αγγέλλω</o>,</f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H5046\">נגד</h> hi.;]</e> </et> <s n=\"1.\"><b>to bring back word</b>, <b>report</b> (Æsch., Thuc., al.): <r v=\"John.5.15\"></r> (WH, <g>εἶπεν</g>), <r v=\"Acts.14.27\"></r> <r v=\"Acts.15.4\"></r>, <r v=\"2Cor.7.7\"></r> </s> <s n=\"2.\">Later, = <x><g>ἀπαγγέλλω</g></x> (MM, <i>VGT</i>, s.v.), <b>to announce, declare</b> (LXX; Cremer, 24): <r v=\"Matt.28.11\"></r> (WH, <g>ἀπ-</g>), <r v=\"John.4.25\"></r> <r v=\"John.16.13-John.16.15\"></r>, <r v=\"Acts.19.18\"></r> <r v=\"Acts.20.20\"></r>, <r v=\"Acts.20.27\"></r> <r v=\"Rom.15.21\"></r>, <r v=\"1Pet.1.12\"></r>, <r v=\"1John.1.5\"></r>.†</s>"},"G331":{"l":"ἀνάθεμα","o":7,"ar":"<f>† <o>ἀνάθεμα</o>، <g>-τος, τό</g></f> <s n=\"1.\">بالمعنى الأصلي = <g>τὸ ἀνατιθέμένον</g>، <b>ما يُوضَع جانبًا</b> ليُحفَظ، <b>تقدمة نذرية</b> (مثل <g>ἀνάθημα</g> في <r v=\"2Macc.2.13\"></r>، <r v=\"Luke.21.5\"></r>). </s> <s n=\"2.\">[في السبعينية مقابلًا لـ <h n=\"H2764\">חֵרֶם</h>،] <b>المُحرَّم، الشيء المكرَّس لله</b> (قارن <r v=\"Lev.27.28-Lev.27.29\"></r>)، ومن ثمّ؛ <s n=\"(a)\">عن الحكم المنطوق (<r v=\"Deut.13.15\"></r>)، <b>لعنة</b>: <r v=\"Acts.23.14\"></r>؛ </s> <s n=\"(b)\">عن الموضوع الذي تقع عليه اللعنة، <b>محروم، ملعون</b> (<r v=\"Deut.7.26\"></r>): <r v=\"Rom.9.3\"></r>، <r v=\"1Cor.12.3\"></r>، <r v=\"1Cor.16.22\"></r>، <r v=\"Gal.1.8\"></r>، <r v=\"Gal.1.9\"></r> (قارن <r v=\"Gal.1.8\"></r>، <r v=\"Gal.1.9\"></r>).†</s> </s>","en":"<f>† <o>ἀνάθεμα</o>, <g>-τος, τό</g></f> <et> <e t=\"derivation\">(&lt; <x><g>ἀνατίθημι</g></x>),</e> <e t=\"derivation\">Hellenistic for Attic <g>ἀνάθημα</g> (Bl., § 27, 2); </e> </et> <s n=\"1.\">prop. = <g>τὸ ἀνατιθέμένον</g>, <b>that which is laid by</b> to be kept, <b>a votive offering</b> (as <g>ἀνάθημα</g> in <r v=\"2Macc.2.13\"></r>, <r v=\"Luke.21.5\"></r>—where LT read <g>-θεμα</g>, v. M, <i>Pr.</i>, 46). </s> <s n=\"2.\">[As equiv. in LXX for <h n=\"H2764\">חֵרֶם</h>,] <b>devoted, a thing devoted to God</b> (v. Driver, De., 98 f., and cf. <r v=\"Lev.27.28-Lev.27.29\"></r>), hence; <s n=\"(a)\">of the sentence pronounced (<r v=\"Deut.13.15\"></r>), <b>a curse</b>: <r v=\"Acts.23.14\"></r>; </s> <s n=\"(b)\">of the object on which the curse is laid, <b>accursed</b> (<r v=\"Deut.7.26\"></r>): <r v=\"Rom.9.3\"></r>, <r v=\"1Cor.12.3\"></r> <r v=\"1Cor.16.22\"></r>, <r v=\"Gal.1.8\"></r>, <r v=\"Gal.1.9\"></r> (v. <i>ICC</i> on Ro.; Lft., <r v=\"Gal.1.8\"></r>, <r v=\"Gal.1.9\"></r>; Cremer, 547; Tr., <i>Syn.</i>, § v; MM, <i>VGT</i>, s.v.).†</s> </s>"},"G337":{"l":"ἀναιρέω","o":25,"ar":"<f><o>ἀν-αιρέω</o>، <g>-ῶ </g> </f> <s n=\"1.\"><b>يرفع، يلتقط</b>: الصيغة الوسطى، <r v=\"Acts.7.21\"></r>. </s> <s n=\"2.\"><b>يزيل</b>، <b>يُبطل</b>، <b>يُهلك</b>؛ <s n=\"(a)\">عن الأشياء: <r v=\"Heb.10.9\"></r>؛ </s> <s n=\"(b)\">عن الأشخاص، <b>يقتل</b>: <r v=\"Matt.2.16\"></r>، <r v=\"Luke.22.2\"></r>، <r v=\"Luke.23.32\"></r>، <r v=\"Acts.2.23\"></r>، <r v=\"Acts.5.33\"></r>، <r v=\"Acts.5.36\"></r>، <r v=\"Acts.7.28\"></r>، <r v=\"Acts.9.23-Acts.9.24\"></r>، <r v=\"Acts.9.29\"></r>، <r v=\"Acts.10.39\"></r>، <r v=\"Acts.12.2\"></r>، <r v=\"Acts.13.28\"></r>، <r v=\"Acts.16.27\"></r>، <r v=\"Acts.22.20\"></r>، <r v=\"Acts.23.15\"></r>، <r v=\"Acts.23.21\"></r>، <r v=\"Acts.23.27\"></r>، <r v=\"Acts.25.3\"></r>، <r v=\"Acts.26.10\"></r>، <r v=\"2Thess.2.8\"></r>.†</s> </s>","en":"<f><o>ἀν-αιρέω</o>, <g>-ῶ </g></f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H2026\">הרג</h> hi., <h n=\"H4191\">מֵת</h> hi., <h n=\"H5221\">נכה</h> hi., etc.;]</e> </et> <s n=\"1.\"><b>to take up</b>: mid., <r v=\"Acts.7.21\"></r>. </s> <s n=\"2.\"><b>to take away</b>, <b>make an end of</b>, <b>destroy</b> (for late exx. of various senses, v. MM, <i>VGT</i>, s.v.); <s n=\"(a)\">of things (as freq. in cl. of laws, etc.): <r v=\"Heb.10.9\"></r>; </s> <s n=\"(b)\">of persons, <b>to kill</b>: <r v=\"Matt.2.16\"></r>, <r v=\"Luke.22.2\"></r> <r v=\"Luke.23.32\"></r>, <r v=\"Acts.2.23\"></r> <r v=\"Acts.5.33\"></r>, <r v=\"Acts.5.36\"></r> <r v=\"Acts.7.28\"></r> <r v=\"Acts.9.23-Acts.9.24\"></r>, <r v=\"Acts.9.29\"></r> <r v=\"Acts.10.39\"></r> <r v=\"Acts.12.2\"></r> <r v=\"Acts.13.28\"></r> <r v=\"Acts.16.27\"></r> <r v=\"Acts.22.20\"></r> <r v=\"Acts.23.15\"></r>, <r v=\"Acts.23.21\"></r> <r v=\"Acts.23.27\"></r> <r v=\"Acts.25.3\"></r> <r v=\"Acts.26.10\"></r>, <r v=\"2Thess.2.8\"></r>, WH, txt., R, txt.†</s> </s>"},"G366":{"l":"ἀνανήφω","o":1,"ar":"<f>* <o>ἀνα-νήφω </o></f> <s><b>يصحو، يعود إلى الرشد</b>: مجازيًا، <r v=\"2Tim.2.26\"></r> (قارن <x><g>ἐκνήφω</g></x>).†</s>","en":"<f>* <o>ἀνα-νήφω </o></f> <s><b>to return to soberness</b>: metaph., <r v=\"2Tim.2.26\"></r> (cf. <x><g>ἐκνήφω</g></x>).†</s>"},"G350":{"l":"ἀνακρίνω","o":16,"ar":"<f><o>ἀνα-κρίνω </o></f> <s><b>يفحص</b>، <b>يتحقّق</b>، <b>يستجوب</b>: <r v=\"Acts.17.11\"></r>، <r v=\"1Cor.2.14\"></r>، <r v=\"1Cor.2.15\"></r> <r v=\"1Cor.4.3\"></r>، <r v=\"1Cor.4.4\"></r> <r v=\"1Cor.9.3\"></r> <r v=\"1Cor.10.25\"></r> <r v=\"1Cor.10.27\"></r> <r v=\"1Cor.14.24\"></r>؛ بالمعنى القضائي (وخاصةً عن الاستجواب بالتعذيب)، <r v=\"Luke.23.14\"></r>، <r v=\"Acts.4.9\"></r> <r v=\"Acts.12.19\"></r> <r v=\"Acts.24.8\"></r> <r v=\"Acts.28.18\"></r>.†</s>","en":"<f><o>ἀνα-κρίνω </o></f> <et> <e t=\"septuagint\">[in LXX: <r v=\"1Sam.20.12\"></r> (<h n=\"H2713\">חקר</h>), <r v=\"Sus.1.13\"></r>, <r v=\"Sus.1.48\"></r>, <r v=\"Sus.1.51\"></r>*;]</e> </et> <s><b>to examine</b>, <b>investigate</b>, <b>question</b> (Lft., <i>Notes</i>, 181 f.): <r v=\"Acts.17.11\"></r>, <r v=\"1Cor.2.14\"></r>, <r v=\"1Cor.2.15\"></r> <r v=\"1Cor.4.3\"></r>, <r v=\"1Cor.4.4\"></r> <r v=\"1Cor.9.3\"></r> <r v=\"1Cor.10.25\"></r> <r v=\"1Cor.10.27\"></r> <r v=\"1Cor.14.24\"></r>; in forensic sense (MM, <i>VGT</i>, s.v.; esp. of examination by torture; v. Field, <i>Notes</i>, 120 f.), <r v=\"Luke.23.14\"></r>, <r v=\"Acts.4.9\"></r> <r v=\"Acts.12.19\"></r> <r v=\"Acts.24.8\"></r> <r v=\"Acts.28.18\"></r>.†</s> <sy><i>SYN.</i>: v.s. <x><g>ἐξετάζω</g></x>.</sy>"},"G343":{"l":"ἀνακαλύπτω","o":2,"ar":"<f><o>ἀνα-καλύπτω </o></f> <s><b>يكشف، يرفع الغطاء</b>: مجازيًا عن إزالة ما يعيق إدراك الأمور الروحية، <r v=\"2Cor.3.14\"></r> <r v=\"2Cor.3.18\"></r>.†</s>","en":"<f><o>ἀνα-καλύπτω </o></f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H1540\">גָּלָה</h> ni., pi.;]</e> </et> <s><b>to unveil</b>: metaph. of removing hindrance to perception of spiritual things, <r v=\"2Cor.3.14\"></r> <r v=\"2Cor.3.18\"></r>.†</s>"},"G386":{"l":"ἀνάστασις","o":42,"ar":"<f><o>ἀνά-στασις</o>، <g>-εως, ἡ</g></f> <s n=\"1.\"><b>إقامة</b>، <b>إيقاظ</b>، <b>قيام</b>: <r v=\"Luke.2.34\"></r>.</s> <s n=\"2.\"><b>قيامة من الأموات</b>؛ <s n=\"(a)\">عن المسيح: <r v=\"Acts.1.22\"></r> <r v=\"Acts.2.31\"></r> <r v=\"Acts.4.33\"></r>، <r v=\"Rom.6.5\"></r>، <r v=\"Phil.3.10\"></r>، <r v=\"1Pet.3.21\"></r>؛ <g>ἐξ ἀ. νεκρῶν</g>، <r v=\"Rom.1.4\"></r>؛ <g>ἐκ νεκρῶν</g>، <r v=\"1Pet.1.3\"></r>؛</s> <s n=\"(b)\">عن أشخاص في تاريخ العهد القديم (مثلاً <r v=\"1Kgs.17.17\"></r> وما يليه): <r v=\"Heb.11.35\"></r>؛</s> <s n=\"(c)\">عن القيامة العامة: <r v=\"Matt.22.23\"></r>، <r v=\"Matt.22.28\"></r>، <r v=\"Matt.22.30\"></r>، <r v=\"Mark.12.18\"></r>، <r v=\"Mark.12.23\"></r>، <r v=\"Luke.20.27\"></r>، <r v=\"Luke.20.33\"></r>، <r v=\"Luke.20.36\"></r>، <r v=\"John.11.24\"></r>، <r v=\"Acts.17.18\"></r> <r v=\"Acts.23.8\"></r> <r v=\"Acts.24.15\"></r>، <r v=\"2Tim.2.18\"></r>؛ <g>ἀ. ἐκ νεκρῶν</g>، <r v=\"Luke.20.35\"></r>، <r v=\"Acts.4.2\"></r>؛ <g>τῶν νεκρῶν</g>، <r v=\"Matt.22.31\"></r>، <r v=\"Acts.17.32\"></r> <r v=\"Acts.23.6\"></r> <r v=\"Acts.24.21\"></r> <r v=\"Acts.26.23\"></r>، <r v=\"1Cor.15.12\"></r>، <r v=\"1Cor.5.13\"></r>، <r v=\"1Cor.15.21\"></r>، <r v=\"1Cor.15.42\"></r>، <r v=\"Heb.6.2\"></r>؛ <g>ἀ. ζωῆς</g>: قيامة الحياة (قارن <r v=\"2Macc.7.14\"></r>، <g>ἀ. εἰς ζωήν</g>) و<g>ἀ. τ. κρίσεως</g>: قيامة الدينونة، <r v=\"John.5.29\"></r>؛ <g>ἀ. τ. δικαίων</g>، <r v=\"Luke.14.14\"></r>؛ <g>κρείττων ἀ.</g>، <r v=\"Heb.11.35\"></r>؛ وعن <g>ἡ ἀ. ἡ πρώτη</g> (القيامة الأولى)، <r v=\"Rev.20.5\"></r>، <r v=\"Rev.20.6\"></r>؛ وبالكناية عن المسيح بوصفه مصدر <g>ἀ.</g>، <r v=\"John.11.25\"></r>.†</s> </s>","en":"<f><o>ἀνά-στασις</o>, <g>-εως, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <x><g>ἀνίστημι</g></x>),</e> <e t=\"septuagint\">[in LXX: <r v=\"Zeph.3.8\"></r> (<h n=\"H6965\">קוּם</h>), <r v=\"Lam.3.63\"></r> (<h n=\"H7012\">קִימָה</h>), <r v=\"Ps.66.1\"></r>, <r v=\"Dan.11.20\"></r>, <r v=\"2Macc.7.14\"></r> <r v=\"2Macc.12.43\"></r>*;]</e> </et> <s n=\"1.\"><b>a raising up</b>, <b>awakening</b>, <b>rising</b> (in Inscr. of the erection of a monument, v. MM, <i>VGT</i>, s.v.): <r v=\"Luke.2.34\"></r>.</s> <s n=\"2.\"><b>a rising from the dead</b> (v. <i>DCG</i>, ii, 605<i>b</i>); <s n=\"(a)\">of Christ: <r v=\"Acts.1.22\"></r> <r v=\"Acts.2.31\"></r> <r v=\"Acts.4.33\"></r>, <r v=\"Rom.6.5\"></r>, <r v=\"Phil.3.10\"></r>, <r v=\"1Pet.3.21\"></r>; <g>ἐξ ἀ. νεκρῶν</g>, <r v=\"Rom.1.4\"></r> (<i>ICC</i>, in l.); <g>ἐκ νεκρῶν</g>, <r v=\"1Pet.1.3\"></r>;</s> <s n=\"(b)\">of persons in OT hist. (e.g. <r v=\"1Kgs.17.17\"></r> ff.): <r v=\"Heb.11.35\"></r>;</s> <s n=\"(c)\">of the general resurrection: <r v=\"Matt.22.23\"></r>, <r v=\"Matt.22.28\"></r>, <r v=\"Matt.22.30\"></r>, <r v=\"Mark.12.18\"></r>, <r v=\"Mark.12.23\"></r>, <r v=\"Luke.20.27\"></r>, <r v=\"Luke.20.33\"></r>, <r v=\"Luke.20.36\"></r>, <r v=\"John.11.24\"></r>, <r v=\"Acts.17.18\"></r> <r v=\"Acts.23.8\"></r> <r v=\"Acts.24.15\"></r>, <r v=\"2Tim.2.18\"></r>; <g>ἀ. ἐκ νεκρῶν</g>, <r v=\"Luke.20.35\"></r>, <r v=\"Acts.4.2\"></r>; <g>τῶν νεκρῶν</g>, <r v=\"Matt.22.31\"></r>, <r v=\"Acts.17.32\"></r> <r v=\"Acts.23.6\"></r> <r v=\"Acts.24.21\"></r> <r v=\"Acts.26.23\"></r>, <r v=\"1Cor.15.12\"></r>, <r v=\"1Cor.5.13\"></r>, <r v=\"1Cor.15.21\"></r>, <r v=\"1Cor.15.42\"></r>, <r v=\"Heb.6.2\"></r>; <g>ἀ. ζωῆς</g>, resurrection to life (cf. <r v=\"2Macc.7.14\"></r>, <g>ἀ. εἰς ζωήν</g>) and <g>ἀ. τ. κρίσεως</g>, r. to judgment, <r v=\"John.5.29\"></r>; <g>ἀ. τ. δικαίων</g>, <r v=\"Luke.14.14\"></r>; <g>κρείττων ἀ.</g>, <r v=\"Heb.11.35\"></r>; on <g>ἡ ἀ. ἡ πρώτη</g>, <r v=\"Rev.20.5\"></r>, <r v=\"Rev.20.6\"></r>, v. Swete, in l., Westc. on Jo 5, but v. also Thayer, s.v.; by meton. of Christ as Author of <g>ἀ.</g>, <r v=\"John.11.25\"></r> (v. <i>DB</i>, iv, 231; Cremer, 307).†</s> </s>"},"G382":{"l":"ἀναρίθμητος","o":1,"ar":"<f><o>ἀν-αρίθμητος</o>، <g>-ον</g>،</f> <s><b>لا يُحصى، لا يُعَدّ</b>: <r v=\"Heb.11.12\"></r>.†</s>","en":"<f><o>ἀν-αρίθμητος</o>, <g>-ον</g>,</f> <et> <e t=\"derivation\">(&lt; <x><g>ἀριθμέω</g></x>), [<r v=\"Job.31.25\"></r>, al.],</e> </et> <s><b>innumerable</b>: <r v=\"Heb.11.12\"></r>.†</s>"},"G399":{"l":"ἀναφέρω","o":10,"ar":"<f><o>ἀνα-φέρω</o>،</f> <s n=\"1.\"><b>حمل</b> أو <b>أصعد</b>: مع منصوب الشخص، <r v=\"Matt.17.1\"></r>، <r v=\"Mark.9.2\"></r>؛ المبني للمجهول، <r v=\"Luke.24.51\"></r>؛ <g>ἀ. τ. ἁμαρτίας ἐπὶ τ. ξύλον</g>: <r v=\"1Pet.2.24\"></r>.</s> <s n=\"2.\">في السبعينية والعهد الجديد: <b>قدّم على المذبح</b>، <b>قرّب</b> (قارن <r v=\"1Pet.2.24\"></r>): <g>θυσίας</g>، إلخ، <r v=\"Heb.7.27\"></r> <r v=\"Heb.13.15\"></r>، <r v=\"1Pet.2.5\"></r>؛ <g>ἐπί τ. θυσιαστήριον</g>، <r v=\"Jas.2.21\"></r>.</s> <s n=\"3.\"><b>حمل</b>، <b>احتمل</b> (قارن <r v=\"Num.14.33\"></r>، <r v=\"Isa.53.12\"></r>): <r v=\"Heb.9.28\"></r>.†</s>","en":"<f><o>ἀνα-φέρω</o>,</f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H5927\">עלה</h> hi., also for <h n=\"H6999\">קטר</h> hi., etc.;]</e> </et> <s n=\"1.\"><b>to carry</b> or <b>lead up</b>: c. acc. pers., <r v=\"Matt.17.1\"></r>, <r v=\"Mark.9.2\"></r>; pass., <r v=\"Luke.24.51\"></r> (WH, rejects, R, mg. omits); <g>ἀ. τ. ἁμαρτίας ἐπὶ τ. ξύλον</g> (v. Deiss., <i>BS</i>, 88 f.; <i>ICC</i>, in l.; MM, <i>VGT</i>, s.v.): <r v=\"1Pet.2.24\"></r>.</s> <s n=\"2.\">In LXX and NT, <b>to bring to the altar</b>, <b>to offer</b> (v. Hort on <r v=\"1Pet.2.24\"></r>): <g>θυσίας</g>, etc., <r v=\"Heb.7.27\"></r> <r v=\"Heb.13.15\"></r>, <r v=\"1Pet.2.5\"></r>; <g>ἐπί τ. θυσιαστήριον</g>, <r v=\"Jas.2.21\"></r> (v. Mayor, in l.).</s> <s n=\"3.\"><b>to bear</b>, <b>sustain</b> (cf. <r v=\"Num.14.33\"></r>, <r v=\"Isa.53.12\"></r>): <r v=\"Heb.9.28\"></r>.†</s>"},"G324":{"l":"ἀναδέχομαι","o":2,"ar":"<f>** <o>ἀνα-δέχομαι </o></f> <s n=\"1.\"><b>تقبّل</b>، <b>تعهّد</b>: <g>ἐπαγγελίας</g>، <r v=\"Heb.11.17\"></r>. </s> <s n=\"2.\">= <g>ὑποδέχομαι</g>، <b>استقبل</b>: عن الضيوف، <r v=\"Acts.28.7\"></r>.†</s>","en":"<f>** <o>ἀνα-δέχομαι </o></f> <et> <e t=\"septuagint\">[in LXX: <r v=\"2Macc.6.19\"></r> <r v=\"2Macc.8.36\"></r>*;]</e> </et> <s n=\"1.\"><b>to assume</b>, <b>undertake</b> (in <g>π.</g> freq. as legal term: MM, <i>VGT</i>, s.v.): <g>ἐπαγγελίας</g>, <r v=\"Heb.11.17\"></r>. </s> <s n=\"2.\">= cl. <g>ὑποδέχομαι</g>, <b>to receive</b>: of guests, <r v=\"Acts.28.7\"></r>.†</s>"},"G313":{"l":"ἀναγεννάω","o":2,"ar":"<f>**† <o>ἀνα-γεννάω</o>، <g>-ῶ </g></f> <s><b>وَلَد ثانيةً</b>: مجازيًا، عن الولادة الروحية، <r v=\"1Pet.1.3\"></r> <r v=\"1Pet.1.23\"></r>.†</s>","en":"<f>**† <o>ἀνα-γεννάω</o>, <g>-ῶ </g></f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Sir.0.17\"></r> <h>א</h>* (ΑΒ<h>א</h><i>c</i> <g>παρα-</g>)*;]</e> </et> <s><b>to beget again</b>: metaph., of spiritual birth, <r v=\"1Pet.1.3\"></r> <r v=\"1Pet.1.23\"></r> (cf. Cremer, 147; MM, <i>VGT</i>, s.v.).†</s>"},"G340":{"l":"ἀνακαινίζω","o":1,"ar":"<f><o>ἀνα-καινίζω</o></f> <s><b>جدّد</b>: <r v=\"Heb.6.6\"></r>.†</s>","en":"<f><o>ἀνα-καινίζω</o></f> <et> <e t=\"derivation\">(&lt; <x><g>καινός</g></x>),</e> <e t=\"septuagint\">[in LXX: <r v=\"2Chr.15.8\"></r>, <r v=\"Ps.103.5\"></r> <r v=\"Ps.104.30\"></r>, <r v=\"Lam.5.21\"></r> (<h n=\"H2318\">חדשׁ</h> pi., hith.)., <r v=\"Ps.39.2\"></r> (<h n=\"H5916\">עכר</h> ni.), <r v=\"1Macc.6.9\"></r>*;]</e> </et> <s><b>to renew</b>: <r v=\"Heb.6.6\"></r> (Isocr., Plut.).†</s>"},"G388":{"l":"ἀνασταυρόω","o":1,"ar":"<f>* <o>ἀνα-σταυρόω</o>؛</f> <s n=\"1.\">في اليونانية الكلاسيكية: <b>خوزق</b>.</s> <s n=\"2.\">عند الكتّاب المتأخرين: <b>رفع على صليب</b>، <b>صلب</b>.</s> <s n=\"3.\"><b>صلب ثانيةً</b>: <r v=\"Heb.6.6\"></r>.†</s>","en":"<f>* <o>ἀνα-σταυρόω</o>;</f> <s n=\"1.\"><b>to impale</b> (Hdt.).</s> <s n=\"2.\"><b>to raise on a cross</b>, <b>crucify</b> (Polyb., al.).</s> <s n=\"3.\"><b>to crucify again</b>: <r v=\"Heb.6.6\"></r> (v. Westc., in l.).†</s>"},"G372":{"l":"ἀνάπαυσις","o":5,"ar":"<f><o>ἀνά-παυσις</o>، <g>-εως, ή</g></f> <s><b>توقّف</b>، <b>راحة</b>، <b>انتعاش</b>: <r v=\"Matt.11.26\"></r> <r v=\"Matt.12.43\"></r>، <r v=\"Luke.11.24\"></r>، <r v=\"Rev.4.8\"></r> <r v=\"Rev.14.11\"></r>.†</s>","en":"<f><o>ἀνά-παυσις</o>, <g>-εως, ή</g></f> <et> <e t=\"derivation\">(<x><g>ἀνάπαύω</g></x>),</e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H5117\">נוּחַ</h> and its derivatives, <h n=\"H7676\">שַׁבָּת</h> and its cognates (Ex, Le);]</e> </et> <s><b>cessation</b>, <b>rest</b>, <b>refreshment</b>: <r v=\"Matt.11.26\"></r> <r v=\"Matt.12.43\"></r>, <r v=\"Luke.11.24\"></r>, <r v=\"Rev.4.8\"></r> <r v=\"Rev.14.11\"></r>.†</s> <sy><i>SYN.</i>: <x><g>ἄνεσις</g></x> (lit, the relaxation of the strings of a lyre), prop. signifies the rest or ease which comes from the relaxation of unfavourable conditions, as, e.g. affliction: <x><g>ἀνάπ.</g></x>, the rest which comes from the temporary cessation of labour (v. Tr., <i>Syn.</i>, § xl; Cremer, 827; MM, <i>VGT</i>, s.v.)</sy>"},"G317":{"l":"ἀναγκαστῶς","o":1,"ar":"<f>* <o>ἀναγκαστῶς </o></f> ظرف، <s><b>اضطرارًا</b> أو <b>قسرًا</b>: عكس <g>ἑκουσίως</g>، <r v=\"1Pet.5.2\"></r> (نادر).†</s>","en":"<f>* <o>ἀναγκαστῶς </o></f> adv., <s><b>necessarily</b> or <b>by constraint</b>: opp. to <g>ἑκουσίως</g>, <r v=\"1Pet.5.2\"></r> (rare).†</s>"},"G395":{"l":"ἀνατολή","o":11,"ar":"<f><o>ἀνατολή</o>، <g>-ῆς, ἡ</g></f> <s n=\"1.\"><b>طلوع، شروق</b>: عن النور، <r v=\"Luke.1.78\"></r>.</s> <s n=\"2.\"><b>مشرق الشمس</b>، <b>الشرق</b>: <r v=\"Matt.2.2\"></r>، <r v=\"Matt.2.9\"></r>، <r v=\"Rev.21.13\"></r>؛ <g>ἀ. ἡλίου</g>، <r v=\"Rev.7.2\"></r>، <r v=\"Rev.16.12\"></r>؛ في الجمع، <r v=\"Matt.2.1\"></r>، <r v=\"Matt.8.11\"></r>، <r v=\"Matt.24.27\"></r>، <r v=\"Luke.13.29\"></r>.†</s>","en":"<f><o>ἀνατολή</o>, <g>-ῆς, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <x><g>ἀνατέλλω</g></x>),</e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H4217\">מִזְרָח</h>, <h n=\"H6921\">קָדִים</h>;]</e> </et> <s n=\"1.\"><b>a rising</b>: of light, <r v=\"Luke.1.78\"></r>.</s> <s n=\"2.\"><b>the sun-rising</b>, <b>the east</b> (MM, <i>VGT</i>, s.v.): <r v=\"Matt.2.2\"></r>, <r v=\"Matt.2.9\"></r>, <r v=\"Rev.21.13\"></r>; <g>ἀ. ἡλίου</g>, <r v=\"Rev.7.2\"></r> <r v=\"Rev.16.12\"></r> (WΗ, pl.); pl., <r v=\"Matt.2.1\"></r> <r v=\"Matt.8.11\"></r> <r v=\"Matt.24.27\"></r>, <r v=\"Luke.13.29\"></r>.†</s>"},"G344":{"l":"ἀνακάμπτω","o":4,"ar":"<f><o>ἀνα-κάμπτω</o>،</f> <s n=\"1.\">متعدٍّ، <b>ثنى</b> أو <b>ردّ إلى الوراء</b>. </s> <s n=\"2.\">لازم، <b>رجع، عاد</b>: <r v=\"Matt.2.12\"></r>، <r v=\"Acts.18.21\"></r>، <r v=\"Heb.11.15\"></r>؛ مجازيًا، <r v=\"Luke.10.6\"></r>.†</s>","en":"<f><o>ἀνα-κάμπτω</o>,</f> <et> <e t=\"septuagint\">[in LXX: <r v=\"1Chr.19.5\"></r>, <r v=\"Jer.3.1\"></r>, al. (<h n=\"H7725\">שׁוּב</h>), <r v=\"Jer.15.5\"></r> (<h n=\"H5493\">סוּר</h>);]</e> </et> <s n=\"1.\">trans., <b>to bend</b> or <b>turn back</b>. </s> <s n=\"2.\">Intrans., <b>to return</b>: <r v=\"Matt.2.12\"></r>, <r v=\"Acts.18.21\"></r>, <r v=\"Heb.11.15\"></r>; metaph. (cf. MM, <i>VGT</i>, s.v.), <r v=\"Luke.10.6\"></r>.†</s>"},"G381":{"l":"ἀνάπτω","o":2,"ar":"<f><o>ἀν-άπτω</o>،</f> <s><b>أوقد، أشعل</b>: <r v=\"Luke.12.49\"></r>، <r v=\"Jas.3.5\"></r>.†</s>","en":"<f><o>ἀν-άπτω</o>,</f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H3318\">יצת</h>;]</e> </et> <s><b>to kindle</b>: <r v=\"Luke.12.49\"></r>, <r v=\"Jas.3.5\"></r> (MM, <i>VGT</i>, s.v.).†</s>"},"G393":{"l":"ἀνατέλλω","o":9,"ar":"<f><o>ἀνα-τέλλω</o>،</f> <s n=\"1.\">متعدٍّ، <b>أطلع، جعله يُشرق</b>: <r v=\"Matt.5.45\"></r>.</s> <s n=\"2.\">لازم، <b>أشرق، طلع</b>: <g>φῶς</g>، <r v=\"Matt.4.16\"></r> (= <r v=\"Isa.9.1\"></r>)؛ <g>ὁ ἥλιος</g>، <r v=\"Matt.13.6\"></r>، <r v=\"Mark.4.6\"></r>، <r v=\"Mark.16.2\"></r>، <r v=\"Jas.1.11\"></r>؛ <g>νεφέλη</g>، <r v=\"Luke.12.54\"></r>؛ <g>φωσφόρος</g>، <r v=\"2Pet.1.19\"></r>؛ <g>ὁ Κύριος</g>، على الأرجح إشارةً إلى استعارة الشمس أو النجم، <r v=\"Heb.7.14\"></r> (قارن <x><g>ἐξ-ανατέλλω</g></x>).†</s>","en":"<f><o>ἀνα-τέλλω</o>,</f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H6779\">צמח</h>, <h n=\"H6524\">פּרח</h>, <h n=\"H2224\">זרח</h>, etc.;]</e> </et> <s n=\"1.\">trans., <b>to cause to rise</b>: <r v=\"Matt.5.45\"></r>.</s> <s n=\"2.\">Intrans., <b>to rise</b>: <g>φῶς</g>, <r v=\"Matt.4.16\"></r> (= <r v=\"Isa.9.1\"></r>); <g>ὁ ἥλιος</g>, <r v=\"Matt.13.6\"></r>, <r v=\"Mark.4.6\"></r> <r v=\"Mark.16.2\"></r>, <r v=\"Jas.1.11\"></r>; <g>νεφέλη</g>, <r v=\"Luke.12.54\"></r>; <g>φωσφόρος</g>, <r v=\"2Pet.1.19\"></r>; <g>ὁ Κύριος</g>, prob. with ref. to metaph. of sun or star, <r v=\"Heb.7.14\"></r> (cf. <x><g>ἐξ-ανατέλλω</g></x>).†</s>"},"G357":{"l":"ἀναλογίζομαι","o":1,"ar":"<f>** <o>ἀνα-λογίζομαι </o></f> <s><b>تفكّر في، تأمّل</b>: <r v=\"Heb.12.3\"></r>.†</s>","en":"<f>** <o>ἀνα-λογίζομαι </o></f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Wis.17.13\"></r> <h>א</h>, <r v=\"2Macc.12.43\"></r> A, <r v=\"3Macc.7.7\"></r>*;]</e> </et> <s><b>to consider</b>: <r v=\"Heb.12.3\"></r> (MM, <i>VGT</i>, s.v.).†</s>"},"G333":{"l":"ἀναθεωρέω","o":2,"ar":"<f>† <o>ἀνα-θεωρέω</o>، <g>-ῶ </g></f> <s><b>يتأمّل بتدقيق</b>، <b>ينظر مليًّا</b>: <r v=\"Acts.17.23\"></r>، <r v=\"Heb.13.7\"></r>.†</s>","en":"<f>† <o>ἀνα-θεωρέω</o>, <g>-ῶ </g></f> <s><b>to observe carefully</b>, <b>consider well</b>: <r v=\"Acts.17.23\"></r>, <r v=\"Heb.13.7\"></r> (Diod., al.).†</s>"},"G301":{"l":"Ἀμώς","o":83,"ar":"<f><o>Ἀμώς</o>، <g>ὁ </g> لا يُصرَّف (العبرية <h n=\"H531\">אָמוֹץ</h>، <r v=\"Isa.1.1\"></r>؛ <h n=\"H5986\">עָמוֹס</h>، <r v=\"Amos.1.1\"></r>؛ <h n=\"H526\">אָמוֹן</h>، <r v=\"2Kgs.21.18\"></r> وما يليه)؛</f> <s n=\"1.\">كما في <r v=\"2Kgs.21.18\"></r> وما يليه (<g>Α. Ἀμμών</g>)، <b>آمون</b>: <r v=\"Matt.1.10\"></r>. </s> <s n=\"2.\"><b>عاموس</b>: <r v=\"Luke.3.25\"></r>.†</s>","en":"<f><o>Ἀμώς</o>, <g>ὁ </g> indecl. (Heb. <h n=\"H531\">אָמוֹץ</h>, <r v=\"Isa.1.1\"></r>; <h n=\"H5986\">עָמוֹס</h>, <r v=\"Amos.1.1\"></r>; <h n=\"H526\">אָמוֹן</h>, <r v=\"2Kgs.21.18\"></r> ff. B);</f> <s n=\"1.\">as in <r v=\"2Kgs.21.18\"></r> ff. B (<g>Α. Ἀμμών</g>; Jos., <g>Ἀμμών</g>, <g>Ἄμωσσς</g>), <b>Amon</b>: <r v=\"Matt.1.10\"></r>. </s> <s n=\"2.\"><b>Amos</b>: <r v=\"Luke.3.25\"></r>.†</s>"},"G327":{"l":"ἀναζητέω","o":3,"ar":"<f><o>ἀνα-ζητέω</o>، <g>-ῶ </g></f> <s><b>بحث عن</b> أو <b>فتَّش بتدقيق</b> (ولا سيما في البحث عن أشخاص، مع تضمين معنى المشقة): <r v=\"Luke.2.44\"></r>، <r v=\"Luke.2.45\"></r>، <r v=\"Acts.11.25\"></r>.†</s>","en":"<f><o>ἀνα-ζητέω</o>, <g>-ῶ </g></f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Job.3.4\"></r> (<h n=\"H1875\">דרשׁ</h>), <r v=\"Job.10.6\"></r> (<h n=\"H1245\">בּקשׁ</h> pi.), <r v=\"2Macc.13.21\"></r>*;]</e> </et> <s><b>to look for</b> or <b>seek carefully</b> (\"specially of searching for human beings, with an implication of difficulty\": MM, <i>VGT</i>, s.v.): <r v=\"Luke.2.44\"></r>, <r v=\"Luke.2.45\"></r>, <r v=\"Acts.11.25\"></r>.†</s>"},"G392":{"l":"ἀνατάσσομαι","o":1,"ar":"<f>† <o>ἀνα-τάσσομαι</o>،</f> <s><b>رتَّب، نظَّم</b>، <b>جمع من الذاكرة</b>: <r v=\"Luke.1.1\"></r>.†</s>","en":"<f>† <o>ἀνα-τάσσομαι</o>,</f> <et> <e t=\"septuagint\">[in LXX only as v.l. (Ald.) in <r v=\"Eccl.2.20\"></r>;]</e> </et> <s><b>to arrange in order</b>, <b>bring together from memory</b> (Blass., <i>Phil. Gosp.</i>, 14 ff.; MM, <i>VGT</i>, s.v.): <r v=\"Luke.1.1\"></r>.†</s>"},"G368":{"l":"ἀναντίρητος","o":1,"ar":"<f>† <o>ἀν-αντί-ρητος</o></f> <s><b>لا يُعترَض عليه</b>، <b>لا يُنكَر</b>: <r v=\"Acts.19.36\"></r>.†</s>","en":"<f>† <o>ἀν-αντί-ρητος</o></f> <et> <e t=\"derivation\">(T, <g>-ρρητος</g>), <g>-ον</g> (&lt; <x><g>ῥητός</g></x>, <i>spoken</i>), </e> <e t=\"septuagint\">[in Sm.: <r v=\"Job.11.2\"></r> <r v=\"Job.33.13\"></r>*;]</e> </et> <s><b>not to be contradicted</b>, <b>undeniable</b>: <r v=\"Acts.19.36\"></r> (MM, <i>VGT</i>, s.v.).†</s>"},"G319":{"l":"ἀναγνωρίζω","o":1,"ar":"<f><o>ἀνα-γνωρίζω </o></f> <s><b>تعرَّف على</b>: <r v=\"Acts.7.13\"></r>.†</s>","en":"<f><o>ἀνα-γνωρίζω </o></f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Gen.45.1\"></r> (<h n=\"H3045\">ידע</h> hith.)*;]</e> </et> <s><b>to recognize</b>: <r v=\"Acts.7.13\"></r> (WH, txt., <g>ἐγνωρίσθη</g>).†</s>"},"G349":{"l":"ἀνακράζω","o":5,"ar":"<f><o>ἀνα-κράζω </o></f> <s><b>صرخ</b>، <b>صاح</b>: <r v=\"Mark.1.23\"></r> <r v=\"Mark.6.49\"></r>، <r v=\"Luke.4.33\"></r> <r v=\"Luke.8.28\"></r> <r v=\"Luke.23.18\"></r>.†</s>","en":"<f><o>ἀνα-κράζω </o></f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H7121\">קרא</h>, etc.;]</e> </et> <s><b>to cry out</b>, <b>shout</b>: <r v=\"Mark.1.23\"></r> <r v=\"Mark.6.49\"></r>, <r v=\"Luke.4.33\"></r> <r v=\"Luke.8.28\"></r> <r v=\"Luke.23.18\"></r>.†</s>"},"G307":{"l":"ἀναβιβάζω","o":1,"ar":"<f><o>ἀνα-βιβάζω</o></f> <s><b>أصعد</b>، <b>جذب إلى أعلى</b>، كالسفينة: <g>σαγήνην</g>، <r v=\"Matt.13.48\"></r>.†</s>","en":"<f><o>ἀνα-βιβάζω</o></f> <et> <e t=\"derivation\">(causal of <x><g>ἀναβαίνω</g></x>),</e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H5927\">עלה</h> hi., also for <h n=\"H7392\">רכב</h> hi., etc.;]</e> </et> <s><b>to make go up</b>, <b>draw up</b>, as a ship (Xen.): <g>σαγήνην</g>, <r v=\"Matt.13.48\"></r> (metaph., MM, <i>VGT</i>, s.v.).†</s>"},"G358":{"l":"ἄναλος","o":1,"ar":"<f>** <o>ἄναλος</o>، <g>-ον</g></f> <s><b>بلا ملح</b>، <b>تَفِه</b>: <r v=\"Mark.9.50\"></r>.†</s>","en":"<f>** <o>ἄναλος</o>, <g>-ον</g></f> <et> <e t=\"derivation\">(&lt; <x><g>ἅλς</g></x>),</e> <e t=\"septuagint\">[in Aq.: <r v=\"Ezek.13.10\"></r>, <r v=\"Ezek.13.11\"></r>, <r v=\"Ezek.13.15\"></r> <r v=\"Ezek.22.28\"></r>*;]</e> </et> <s><b>saltless</b>, <b>insipid</b>: <r v=\"Mark.9.50\"></r>.†</s>"},"G332":{"l":"ἀναθεματίζω","o":4,"ar":"<f>† <o>ἀνα-θεματίζω</o></f> <s><b>يخصّص للهلاك</b>، <b>يعلن</b> أو <b>يستنزل الحِرْم (اللعنة)</b>: مطلقًا، <r v=\"Mark.14.71\"></r>؛ <g>ἐαντόν</g>، <b>يُلزم نفسه بلعنة</b>: <r v=\"Acts.23.12\"></r>، <r v=\"Acts.23.14\"></r> <r v=\"Acts.23.21\"></r> (قارن <g>καταναθεματίζω</g>).†</s>","en":"<f>† <o>ἀνα-θεματίζω</o></f> <et> <e t=\"derivation\">(&lt; <x><g>ἀνίθεμα</g></x>),</e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H2763\">חרם</h> hi. (<r v=\"Num.21.2\"></r>, <r v=\"1Sam.15.3\"></r>, al.), <r v=\"1Macc.5.5\"></r>;]</e> </et> <s><b>to devote to destruction</b>, <b>declare</b> or <b>invoke anathema</b>: absol., <r v=\"Mark.14.71\"></r>; <g>ἐαντόν</g>, <b>to bind oneself under a curse</b>: <r v=\"Acts.23.12\"></r>, <r v=\"Acts.23.14\"></r> <r v=\"Acts.23.21\"></r> (cf. <g>καταναθεματίζω</g>, and on the occurrence of the word in <g>π.</g>, v. Deiss., <i>LAE</i>, 92 f.; MM, <i>VGT</i>, s.v.).†</s>"},"G383":{"l":"ἀνασείω","o":2,"ar":"<f>** <o>ἀνα-σείω</o>،</f> <s n=\"1.\">في اليونانية الكلاسيكية: <b>ينفض</b>، <b>يهزّ إلى الوراء</b>، <b>يحرّك جيئةً وذهابًا</b>.</s> <s n=\"2.\">عند الكتّاب المتأخرين، <b>يُهيِّج</b>؛ مجازيًا، <b>يثير</b>: <g>τ. ὄχλον</g>، <r v=\"Mark.15.11\"></r>؛ <g>τ. λαόν</g>، <r v=\"Luke.23.5\"></r>.†</s>","en":"<f>** <o>ἀνα-σείω</o>,</f> <et> <e t=\"septuagint\">[in Aq.: <r v=\"1Sam.26.19\"></r>, <r v=\"Job.2.3\"></r>; Aq., Sm.: <r v=\"Isa.36.18\"></r>*;]</e> </et> <s n=\"1.\"><b>to shake out</b>, <b>shake back</b>, <b>move to and fro</b> (Thuc., al.).</s> <s n=\"2.\">In late writers (Diod., al.; v. MM, <i>VGT</i>, s.v.), <b>to stir up</b>; metaph., <b>to excite</b>: <g>τ. ὄχλον</g>, <r v=\"Mark.15.11\"></r>; <g>τ. λαόν</g>, <r v=\"Luke.23.5\"></r>.†</s>"},"G384":{"l":"ἀνασκευάζω","o":1,"ar":"<f>* <o>ἀνα-σκευάζω</o></f> <s>بالمعنى الحرفي <b>يحزم الأمتعة</b>، ومن ثمّ <b>يفكّك</b>، <b>يخرّب</b>، <b>يهدم</b>؛ مجازيًا، <b>يزعزع</b>، <b>يقلب</b>: <g>ψυχάς</g>، <r v=\"Acts.15.24\"></r>.†</s>","en":"<f>* <o>ἀνα-σκευάζω</o></f> <et> <e t=\"derivation\">(&lt; <x><g>σκεῦος</g></x>, <i>a vessel</i>),</e> </et> <s>prop. <b>to pack up baggage</b>, hence, <b>to dismantle</b>, <b>ravage</b>, <b>destroy</b>; metaph., <b>to unsettle</b>, <b>subvert</b> (MM, <i>VGT</i>, s.v.): <g>ψυχάς</g>, <r v=\"Acts.15.24\"></r>.†</s>"},"G397":{"l":"ἀνατρέφω","o":3,"ar":"<f>** <o>ἀνα-τρέφω</o>،</f> <s><b>يربّي</b>، <b>يغذّي</b>، <b>يهذّب</b>، <b>ينشّئ</b>: <r v=\"Luke.4.16\"></r>، <r v=\"Acts.7.20\"></r>، <r v=\"Acts.7.21\"></r> <r v=\"Acts.22.3\"></r>.†</s>","en":"<f>** <o>ἀνα-τρέφω</o>,</f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Wis.7.4\"></r> B, <r v=\"4Macc.10.2\"></r> <r v=\"4Macc.11.15\"></r> <h>א</h>*;]</e> </et> <s><b>to nurse up</b>, <b>nourish</b>, <b>educate</b>, <b>bring up</b>: <r v=\"Luke.4.16\"></r>, WΗ, mg., <r v=\"Acts.7.20\"></r>, <r v=\"Acts.7.21\"></r> <r v=\"Acts.22.3\"></r>.†</s>"},"G304":{"l":"ἀναβαθμός","o":2,"ar":"<f><o>ἀνα-βαθμός</o>، <g>-οῦ, ὁ</g></f> <s n=\"1.\"><b>صعود</b>، <b>مرتقى</b> (في عناوين المزامير 119(120)-133(134)؟).</s> <s n=\"2.\"><b>درجة</b> (في السبعينية)؛ وفي الجمع: <b>درج، سُلّم</b>: <r v=\"Acts.21.35\"></r>، <r v=\"Acts.21.40\"></r>.†</s>","en":"<f><o>ἀνα-βαθμός</o>, <g>-οῦ, ὁ</g></f> <et> <e t=\"derivation\">(&lt; <x><g>ἀναβαίνω</g></x>),</e> <e t=\"septuagint\">[in LXX for <h n=\"H4609\">מַעֲלָה</h>: <r v=\"1Kgs.10.19\"></r>, <r v=\"1Kgs.10.20\"></r>, <r v=\"2Kgs.9.13\"></r> <r v=\"2Kgs.20.9\"></r> ff, <r v=\"2Chr.9.18\"></r>, <r v=\"2Chr.9.19\"></r>, <r v=\"Isa.38.8\"></r>, <r v=\"Ezek.40.6\"></r>, <r v=\"Ezek.40.49\"></r>; <g>ᾠδὴ τῶν ἀ.</g>, <i>tit.</i> 119(120)-133(134)*;]</e> </et> <s n=\"1.\"><b>a going up</b>, <b>an ascent</b> (Pss, <i>tit.</i> 119(120)-133(134) ?).</s> <s n=\"2.\"><b>a step</b> (LXX); pl., <b>a flight of stairs</b>: <r v=\"Acts.21.35\"></r>, <r v=\"Acts.21.40\"></r>. (On the formation <g>-θμός</g>, v. MM, <i>VGT</i>, s.v.)†</s>"},"G310":{"l":"ἀναβοάω","o":1,"ar":"<f><o>ἀνα-βοάω</o>، <g>-ῶ </g></f> <s><b>صرخ</b>: <r v=\"Matt.27.46\"></r>.†</s>","en":"<f><o>ἀνα-βοάω</o>, <g>-ῶ </g></f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H6817\">צעק</h>, <h n=\"H2199\">זעק</h>, <h n=\"H7121\">קרא</h>, etc.;]</e> </et> <s><b>to cry out</b>: <r v=\"Matt.27.46\"></r> (WH, <g>ἐβόησεν</g>; v. MM, <i>VGT</i>, s.v.).†</s>"},"G369":{"l":"ἀναντιρήτως","o":1,"ar":"<f>* <o>ἀν-αντι-ρήτως</o>، </f> ظرف، <s><b>بلا مناقضة</b>، دون اعتراض: <r v=\"Acts.10.29\"></r>.†</s>","en":"<f>* <o>ἀν-αντι-ρήτως</o> (T, <g>-ρρήτως</g>), </f> adv., <s><b>without contradiction</b>: <r v=\"Acts.10.29\"></r>.†</s>"},"G377":{"l":"ἀναπίπτω","o":12,"ar":"<f><o>ἀνα-πίπτω</o>،</f> <s n=\"1.\">في اليونانية الكلاسيكية: <b>سقط إلى الوراء</b>.</s> <s n=\"2.\">عند الكتّاب المتأخرين = <g>ἀνα-κλίνομαι</g>، <b>اتّكأ</b> للطعام: على المائدة، <r v=\"Luke.11.37\"></r>، <r v=\"Luke.14.10\"></r>، <r v=\"Luke.17.7\"></r>، <r v=\"Luke.22.14\"></r>، <r v=\"John.13.12\"></r>، <r v=\"John.21.20\"></r>؛ على الأرض، <r v=\"Matt.15.35\"></r>، <r v=\"Mark.6.40\"></r>، <r v=\"Mark.8.6\"></r>، <r v=\"John.6.10\"></r>؛ <b>اتّكأ إلى الوراء</b>، <r v=\"John.13.25\"></r> (انظر تحت مدخل <g>ἀνάκειμαι</g>، في آخره).†</s>","en":"<f><o>ἀνα-πίπτω</o>,</f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Gen.49.9\"></r> (<h n=\"H3766\">כּרע</h>) <r v=\"Tob.2.1\"></r> <r v=\"Tob.7.8\"></r>, <r v=\"Jdt.12.10\"></r>, <r v=\"Sir.25.18\"></r> <r v=\"Sir.32.2\"></r>, <r v=\"Sus.1.37\"></r>*;]</e> </et> <s n=\"1.\">(cl.) <b>to fall back</b>.</s> <s n=\"2.\">In late writers = <g>ἀνα-κλίνομαι</g>, <b>to recline</b> for a repast (MM, <i>VGT</i>, s.v.): at table, <r v=\"Luke.11.37\"></r> <r v=\"Luke.14.10\"></r> <r v=\"Luke.17.7\"></r> <r v=\"Luke.22.14\"></r>, <r v=\"John.13.12\"></r> <r v=\"John.21.20\"></r>; on the ground, <r v=\"Matt.15.35\"></r>, <r v=\"Mark.6.40\"></r> <r v=\"Mark.8.6\"></r>, <r v=\"John.6.10\"></r>; <b>to lean back</b>, <r v=\"John.13.25\"></r> (T, <g>ἐπιπεσών</g>; v.s. <g>ἀνάκειμαι</g>, ad fin.).†</s> <sy><i>SYN.</i>: <x><g>ἀνάκειμαι</g></x> (q.v.), <x><g>ἀνακλίνομαι</g></x>.</sy>"},"G367":{"l":"Ἀνανίας","o":11,"ar":"<f><o>Ἀνανίας</o>، <g>-α, ὁ</g> (العبرية <h n=\"H2608\">חֲנַנְיָה</h>)، </f> <s><b>حنانيا</b>؛ <s n=\"1.\">من أورشليم: <r v=\"Acts.5.1\"></r>، <r v=\"Acts.5.3\"></r>، <r v=\"Acts.5.5\"></r>. </s> <s n=\"2.\">من دمشق: <r v=\"Acts.9.10-Acts.9.13\"></r>، <r v=\"Acts.9.17\"></r>، <r v=\"Acts.22.12\"></r>. </s> <s n=\"3.\">رئيس الكهنة: <r v=\"Acts.23.2\"></r>، <r v=\"Acts.24.1\"></r>.†</s> </s>","en":"<f><o>Ἀνανίας</o> (WH, <g>Ἁναν-</g>), <g>-α, ὁ</g> (Heb. <h n=\"H2608\">חֲנַנְיָה</h>), </f> <s><b>Ananias</b>; <s n=\"1.\">of Jerusalem: <r v=\"Acts.5.1\"></r>, <r v=\"Acts.5.3\"></r> <r v=\"Acts.5.5\"></r>. </s> <s n=\"2.\">Of Damascus: <r v=\"Acts.9.10-Acts.9.13\"></r>, <r v=\"Acts.9.17\"></r> <r v=\"Acts.22.12\"></r>. </s> <s n=\"3.\">High Priest: <r v=\"Acts.23.2\"></r> <r v=\"Acts.24.1\"></r>.†</s> </s>"},"G322":{"l":"ἀναδείκνυμι","o":2,"ar":"<f><o>ἀνα-δείκνυμι</o>،</f> <s n=\"1.\"><b>رفع وأظهر</b>، <b>أبان</b>، <b>أعلن</b> (قارن <r v=\"2Macc.2.8\"></r>): <r v=\"Acts.1.24\"></r>. </s> <s n=\"2.\"><b>عيّن</b>، <b>أفرز، خصّص</b>: <r v=\"Luke.10.1\"></r>.†</s>","en":"<f><o>ἀνα-δείκνυμι</o>,</f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Hab.3.2\"></r> (<h n=\"H3045\">יָדַע</h>), <r v=\"Dan.1.11\"></r> (<h n=\"H4487\">מָנָה</h>), <r v=\"Dan.1.20\"></r> (<h n=\"H4672\">מָצָא</h>), I Es<i>6</i>, II, III Mac<i>9</i>*;]</e> </et> <s n=\"1.\"><b>to lift up and show</b>, <b>show forth</b>, <b>declare</b> (cf. <r v=\"2Macc.2.8\"></r>, v. MM, <i>VGT</i>, s.v.): <r v=\"Acts.1.24\"></r>. </s> <s n=\"2.\"><b>to consecrate</b>, <b>set apart</b>, (Strab., Plut., Anth.): <r v=\"Luke.10.1\"></r>.†</s>"},"G352":{"l":"ἀνακύπτω","o":4,"ar":"<f><o>ἀνα-κύπτω</o></f> <s><b>انتصب، رفع نفسه</b>؛ <s n=\"(a)\">جسديًا: <r v=\"Luke.13.11\"></r>، <r v=\"John.8.7\"></r>، <r v=\"John.8.10\"></r>؛ </s> <s n=\"(b)\">معنويًا، <b>تشجّع، ابتهج</b>: <r v=\"Luke.21.28\"></r>.†</s> </s>","en":"<f><o>ἀνα-κύπτω</o></f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Job.10.15\"></r> (<h n=\"H5375,H7218\">נָשָׂא רֹאשׁ</h>), <r v=\"Sus.1.35\"></r>*;]</e> </et> <s><b>to lift oneself up</b>; <s n=\"(a)\">bodily; <r v=\"Luke.13.11\"></r>, <r v=\"John.8.7\"></r>, <r v=\"John.8.10\"></r>; </s> <s n=\"(b)\">mentally, <b>to be elated</b>: <r v=\"Luke.21.28\"></r> (cf. MM, <i>VGT</i>, s.v.).†</s> </s>"},"G398":{"l":"ἀναφαίνομαι","o":2,"ar":"<f><o>ἀνα-φαίνομαι</o>،</f> <s><b>أظهر</b>، <b>جعله يظهر</b>: <g>ἀναφάναντες τ. Κύπρον</g>، أي <b>إذ لاحت لهم</b> قبرس: <r v=\"Acts.21.3\"></r>؛ المبني للمجهول، <b>ظهر</b>، <b>استُعلن</b>: <r v=\"Luke.19.11\"></r>.</s>","en":"<f><o>ἀνα-φαίνομαι</o>,</f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H6663\">צדק</h> hi., <h n=\"H1570\">גּלשׁ</h>;]</e> </et> <s><b>to bring to light</b>, <b>make to appear</b>: <g>ἀναφάναντες τ. Κύπρον</g>, i.e. <b>having sighted</b> C.: <r v=\"Acts.21.3\"></r> WH; pass., <b>to appear</b>, <b>be made manifest</b>: <r v=\"Luke.19.11\"></r>.</s>"},"G325":{"l":"ἀναδίδωμι","o":1,"ar":"<f>** <o>ἀνα-δίδωμι </o></f> <s n=\"1.\">في اليونانية الكلاسيكية: <b>أخرج</b>، <b>أطلع</b>، كما عن النباتات. </s> <s n=\"2.\"><b>سلّم</b>، <b>دفع إلى</b>: <r v=\"Acts.23.33\"></r>.†</s>","en":"<f>** <o>ἀνα-δίδωμι </o></f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Sir.1.22\"></r>, <r v=\"2Macc.13.15\"></r>*;]</e> </et> <s n=\"1.\"><b>to give forth</b>, <b>send up</b>, as of plants (Hdt., al.). </s> <s n=\"2.\"><b>to give up</b>, <b>yield</b>, <b>hand over</b> (MM, <i>VGT</i>, s.v.): <r v=\"Acts.23.33\"></r>.†</s>"},"G338":{"l":"ἀναίτιος","o":2,"ar":"<f><o>ἀν-αίτιος</o>، <g>-ον</g></f> <s><b>بلا لوم</b>، <b>بريء</b>: <r v=\"Matt.12.5\"></r>، <r v=\"Matt.12.7\"></r>.†</s>","en":"<f><o>ἀν-αίτιος</o>, <g>-ον</g></f> <et> <e t=\"derivation\">(&lt; <x><g>αἰτία</g></x>),</e> <e t=\"septuagint\">[in LXX: <r v=\"Deut.19.10\"></r>, <r v=\"Deut.19.13\"></r> <r v=\"Deut.21.8\"></r>, <r v=\"Deut.21.9\"></r> (<h n=\"H5355\">נָקִי</h>), <r v=\"Sus.1.62\"></r>, always of <g>αἷμα</g> (of. MM, <i>VGT</i>, s.v.)*;]</e> </et> <s><b>guiltless</b>, <b>innocent</b>: <r v=\"Matt.12.5\"></r>, <r v=\"Matt.12.7\"></r>.†</s>"},"G309":{"l":"ἀνάβλεψις","o":1,"ar":"<f><o>ἀνά-βλεψις</o>، <g>-εως, ή</g></f> <s><b>استرداد البصر</b>: <r v=\"Luke.4.18\"></r> <i>(السبعينية)</i>.†</s>","en":"<f><o>ἀνά-βλεψις</o>, <g>-εως, ή</g></f> <et> <e t=\"derivation\">(&lt; <x><g>ἀναβλέπω</g></x>),</e> <e t=\"septuagint\">[in LXX: <r v=\"Isa.61.1\"></r> (<h n=\"H6495\">פְּקַח־קוֹחַ</h>)*;]</e> </et> <s><b>recovery of sight</b>: <r v=\"Luke.4.18\"></r><i>(LXX)</i>.†</s>"},"G335":{"l":"ἀναιδία","o":1,"ar":"<f>** <o>ἀναιδία</o>، <g>-ας, ἡ</g></f> <s><b>وقاحة</b>، <b>لجاجة (إلحاح)</b>: <r v=\"Luke.11.8\"></r>.†</s>","en":"<f>** <o>ἀναιδία</o> (Rec. <g>-εία</g>, as in cl.), <g>-ας, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <x><g>αἰδώς</g></x>),</e> <e t=\"septuagint\">[in LXX: <r v=\"Sir.25.22\"></r>*;]</e> </et> <s><b>shamelessness</b>, <b>importunity</b>: <r v=\"Luke.11.8\"></r> (for exx. from <g>π.</g>, v. MM, <i>VGT</i>, s.v.).†</s>"},"G334":{"l":"ἀνάθημα","o":1,"ar":"<f>** <o>ἀνάθημα</o>، <g>-τος, τό</g></f> <s><b>هبة منصوبة</b> في هيكل، <b>تقدمة نذرية</b>: <r v=\"Luke.21.5\"></r>.†</s>","en":"<f>** <o>ἀνάθημα</o>, <g>-τος, τό</g></f> <et> <e t=\"derivation\">(cf. <x><g>ἀνάθημα</g></x>, and v. MM, <i>VGT</i>, s.v.),</e> <e t=\"septuagint\">[in LXX often as v.l. for <x><g>ἀνάθεμα</g></x> (<h n=\"H2763\">חֵרֶם</h>), and in <r v=\"Num.21.3\"></r>, <r v=\"Judg.1.17\"></r> for <h n=\"H2767\">חׇרְמָה</h>, but prop. in <r v=\"3Macc.3.17\"></r>, al.;]</e> </et> <s><b>a gift set up</b> in a temple, <b>a votive offering</b>: <r v=\"Luke.21.5\"></r> (LT, <g>-θεμα</g>).†</s>"},"G345":{"l":"ἀνάκειμαι","o":14,"ar":"<f>** <o>ἀνά-κειμαι </o></f> <s n=\"1.\">في اليونانية الكلاسيكية، مبني للمجهول من <g>ἀνατίθημ</g>: <b>وُضع جانبًا</b>، <b>وُضع</b>: <r v=\"Mark.5.40\"></r> (في النص المستلَم). </s> <s n=\"2.\">عند الكتّاب المتأخرين، = <g>κεῖσθαι</g>، <g>κατακεῖσθαι</g>، <b>اتّكأ إلى المائدة</b>: <r v=\"Matt.26.20\"></r>؛ اسم الفاعل <g>ἀνακείμενος</g>، <r v=\"Matt.9.10\"></r> <r v=\"Matt.22.10\"></r>، <r v=\"Matt.22.11\"></r> <r v=\"Matt.26.7\"></r>، <r v=\"Mark.6.26\"></r> <r v=\"Mark.14.18\"></r> <r v=\"Mark.16.14\"></r>، <r v=\"Luke.22.27\"></r>، <r v=\"John.6.11\"></r> <r v=\"John.12.2\"></r> <r v=\"John.13.23\"></r>، <r v=\"John.13.28\"></r>.†</s>","en":"<f>** <o>ἀνά-κειμαι </o></f> <et> <e t=\"septuagint\">[in LXX: <r v=\"1Esd.4.10\"></r>, <r v=\"Tob.9.6\"></r> <h>א</h>*;]</e> </et> <s n=\"1.\">in cl., as pass. of <g>ἀνατίθημ</g>, <b>to be laid up</b>, <b>laid</b>: <r v=\"Mark.5.40\"></r> Rec. </s> <s n=\"2.\">In late writers (cf. MM, <i>VGT</i>, s.v.) = <g>κεῖσθαι</g>, <g>κατακεῖσθαι</g>, <b>to recline at table</b>: <r v=\"Matt.26.20\"></r>; part. <g>ἀνακείμενος</g>, <r v=\"Matt.9.10\"></r> <r v=\"Matt.22.10\"></r>, <r v=\"Matt.22.11\"></r> <r v=\"Matt.26.7\"></r>, <r v=\"Mark.6.26\"></r> <r v=\"Mark.14.18\"></r> <r v=\"Mark.16.14\"></r>, <r v=\"Luke.22.27\"></r>, <r v=\"John.6.11\"></r> <r v=\"John.12.2\"></r> <r v=\"John.13.23\"></r>, <r v=\"John.13.28\"></r>.†</s> <sy><i>SYN.</i>: <x><g>ἀνακλίνω</g></x>, <x><g>ἀναπίπτω</g></x>, the latter denoting an act rather than a state and thus in <r v=\"John.13.25\"></r> differing from <x><g>ἀνάκειμαι</g></x> (see. <r v=\"John.13.23\"></r>) by indicating a change of position. </sy>"},"G308":{"l":"ἀναβλέπω","o":25,"ar":"<f><o>ἀνα-βλέπω </o></f> <s n=\"1.\"><b>رفع نظره، تطلّع إلى فوق</b>: <r v=\"Mark.8.24\"></r>، وفي مواضع أخرى؛ يليه <g>εἰς</g>، <r v=\"Matt.14.19\"></r>، وفي مواضع أخرى. </s> <s n=\"2.\"><b>استعاد البصر، أبصر</b>: <r v=\"Matt.11.5\"></r>، <r v=\"John.9.11\"></r>، وفي مواضع أخرى.</s>","en":"<f><o>ἀνα-βλέπω </o></f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H5375\">נשׂא</h>;]</e> </et> <s n=\"1.\"><b>to look up</b>: <r v=\"Mark.8.24\"></r>, al.; seq. <g>εἰς</g>, <r v=\"Matt.14.19\"></r>, al. (Xen., Plat.). </s> <s n=\"2.\"><b>to recover sight</b> (Plat., Aristoph.; cf. MM, <i>VGT</i>, s.v.): <r v=\"Matt.11.5\"></r>, <r v=\"John.9.11\"></r>, al.</s>"},"G361":{"l":"ἀναμάρτητος","o":1,"ar":"<f><o>ἀναμάρτητος</o>، <g>-ον</g></f> <s n=\"1.\">في اليونانية الكلاسيكية: <b>لا يُخطئ الهدف</b>، <b>معصوم من الخطأ</b>. </s> <s n=\"2.\">بالمعنى الأدبي، <b>بلا عيب</b>، <b>بلا خطية</b>: <r v=\"John.8.7\"></r>.†</s>","en":"<f><o>ἀναμάρτητος</o>, <g>-ον</g></f> <et> <e t=\"derivation\">(&lt; <x><g>ἁμαρτεῖν</g></x>),</e> <e t=\"septuagint\">[in LXX: <r v=\"Deut.29.19\"></r> (<r v=\"Deut.29.18\"></r>) <r v=\"2Macc.8.4\"></r> <r v=\"2Macc.12.42\"></r>*;]</e> </et> <s n=\"1.\"><b>without missing</b>, <b>unerring</b> (Xen.). </s> <s n=\"2.\">In moral sense, <b>faultless</b> (Plat.), <b>without sin</b>: <r v=\"John.8.7\"></r> (v. Cremer, 102, 634; MM, <i>VGT</i>, s.v.).†</s>"},"G339":{"l":"ἀνακαθίζω","o":2,"ar":"<f>* <o>ἀνα-καθ-ίζω</o></f> <s n=\"1.\">متعدّيًا، <b>أقام، أجلس</b>.</s> <s n=\"2.\">لازمًا، <b>جلس (معتدلاً)</b>: <r v=\"Luke.7.15\"></r>، <r v=\"Acts.9.40\"></r> (يكثر في الكتابات الطبية).†</s>","en":"<f>* <o>ἀνα-καθ-ίζω</o></f> <et> <e t=\"derivation\">(v.s. <x><g>καθίζω</g></x>);</e> </et> <s n=\"1.\">trans., <b>to set up</b>.</s> <s n=\"2.\">Intrans., <b>to sit up</b>: <r v=\"Luke.7.15\"></r> (WH, mg., <g>ἐκάθισεν</g>), <r v=\"Acts.9.40\"></r> (freq. in medical writings: MM, <i>VGT</i>, s.v.).†</s>"},"G376":{"l":"ἀνάπηρος","o":2,"ar":"<f>** <o>ἀνά-πηρος</o>، <g>-ον</g> (<x><g>πηρός</g></x>، <i>مشوَّه</i>)،</f> <s><b>أجدع، مشوَّه الأعضاء</b>، <b>مُقعَد</b>: <r v=\"Luke.14.13\"></r>، <r v=\"Luke.14.21\"></r>.†</s>","en":"<f>** <o>ἀνά-πηρος</o> (WH, <g>-ειρος</g>; v. Field, <i>Notes</i>, 67), <g>-ον</g> (<x><g>πηρός</g></x>, <i>maimed</i>),</f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Tob.14.2\"></r> <h>א</h>, <r v=\"2Macc.8.24\"></r>*;]</e> </et> <s><b>maimed</b>, <b>crippled</b>: <r v=\"Luke.14.13\"></r>, <r v=\"Luke.14.21\"></r>.†</s>"},"G336":{"l":"ἀναίρεσις","o":1,"ar":"<f><o>ἀν-αίρεσις</o>، <g>-εως, ἡ</g></f> <s n=\"1.\">في اليونانية الكلاسيكية: <b>رفع</b> أو <b>إزالة</b>. </s> <s n=\"2.\"><b>إهلاك</b>، <b>قتل</b>، <b>جريمة قتل</b>: <r v=\"Acts.8.1\"></r>.†</s>","en":"<f><o>ἀν-αίρεσις</o>, <g>-εως, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <x><g>ἀναιρέω</g></x>),</e> <e t=\"septuagint\">[in LXX: <r v=\"Num.11.15\"></r> (<h n=\"H2026\">הָרַג</h>), <r v=\"Judg.15.17\"></r> (<h n=\"H7413\">רָמָה</h>), <r v=\"Jdt.15.4\"></r>, <r v=\"2Macc.5.13\"></r>*;]</e> </et> <s n=\"1.\"><b>a taking up</b> or <b>away</b> (Thuc.). </s> <s n=\"2.\"><b>a destroying</b>, <b>slaying</b>, <b>murder</b> (Field, <i>Notes</i>, 116; MM, <i>VGT</i>, s.v.): <r v=\"Acts.8.1\"></r>.†</s>"},"G385":{"l":"ἀνασπάω","o":2,"ar":"<f><o>ἀνα-σπάω</o>، <g>-ῶ</g>،</f> <s><b>انتشل، سحب إلى فوق</b>: <r v=\"Luke.14.5\"></r>، <r v=\"Acts.11.10\"></r>.†</s>","en":"<f><o>ἀνα-σπάω</o>, <g>-ῶ</g>,</f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H3947\">לקח</h>, <h n=\"H5927\">עלה</h> hi.;]</e> </et> <s><b>to draw up</b>: <r v=\"Luke.14.5\"></r>, <r v=\"Acts.11.10\"></r> (in <g>π.</g> of pulling up barley; MM, <i>VGT</i>, s.v.).†</s>"},"G374":{"l":"ἀναπείθω","o":1,"ar":"<f><o>ἀνα-πείθω</o>،</f> <s><b>أقنع</b>، <b>حرّض</b>: <r v=\"Acts.18.13\"></r>.†</s>","en":"<f><o>ἀνα-πείθω</o>,</f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Jer.29.8\"></r> (<h n=\"H5377\">נשׂא</h> hi.), <r v=\"1Macc.1.11\"></r>*;]</e> </et> <s><b>to persuade</b>, <b>incite</b>: <r v=\"Acts.18.13\"></r> (cf. MM, <i>VGT</i>, s.v.).†</s>"},"G347":{"l":"ἀνακλίνω","o":6,"ar":"<f>** <o>ἀνα-κλίνω</o>،</f> <s><b>وضع على</b>، <b>أسند إلى</b>، ومن ثمّ <s n=\"(a)\"><b>أضجع، وضع</b>: <r v=\"Luke.2.7\"></r>؛ </s> <s n=\"(b)\"><b>أتكأ</b>: <r v=\"Mark.6.39\"></r>، <r v=\"Luke.12.37\"></r>. المبني للمجهول، <b>اتّكأ</b>، <b>استلقى</b>: <r v=\"Matt.8.11\"></r> <r v=\"Matt.14.19\"></r>، <r v=\"Luke.13.29\"></r>.† </s> </s>","en":"<f>** <o>ἀνα-κλίνω</o>,</f> <et> <e t=\"septuagint\">[in LXX: <r v=\"3Macc.5.16\"></r>*;]</e> </et> <s><b>to lay upon</b>, <b>lean against</b>, hence, <s n=\"(a)\"><b>to lay down</b>: <r v=\"Luke.2.7\"></r>; </s> <s n=\"(b)\"><b>to make to recline</b>: <r v=\"Mark.6.39\"></r>, WH, mg., <r v=\"Luke.12.37\"></r>. Pass., <b>to lie back</b>, <b>recline</b>: <r v=\"Matt.8.11\"></r> <r v=\"Matt.14.19\"></r>, <r v=\"Luke.13.29\"></r>.† </s> </s> <sy><i>SYN.</i>: <x><g>ἀνάκειμαι</g></x> (q.v.), <x><g>ἀναπίπτω</g></x>.</sy>"},"G351":{"l":"ἀνάκρισις","o":1,"ar":"<f>** <o>ἀνά-κρισις</o>، <g>-εως, ἡ</g>،</f> <s><b>فحص، استجواب</b>: خاصةً عن التحقيق القضائي التمهيدي، <r v=\"Acts.25.26\"></r>.†</s>","en":"<f>** <o>ἀνά-κρισις</o>, <g>-εως, ἡ</g>,</f> <et> <e t=\"septuagint\">[in LXX: <r v=\"3Macc.7.5\"></r>*;]</e> </et> <s><b>an examination</b>: spec. of legal preliminary investigation, <r v=\"Acts.25.26\"></r> (v. MM, <i>VGT</i>, s.v.).†</s>"},"G323":{"l":"ἀνάδειξις","o":1,"ar":"<f>**† <o>ἀνά-δειξις</o>، <g>-εως, ἡ</g></f> <s><b>إظهار</b>، <b>إعلان</b>: <r v=\"Luke.1.80\"></r>.†</s>","en":"<f>**† <o>ἀνά-δειξις</o>, <g>-εως, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <x><g>ἀναδείκνυμι</g></x>),</e> <e t=\"septuagint\">[in LXX: <r v=\"Sir.43.6\"></r>*;]</e> </et> <s><b>a shewing forth</b>, <b>announcement</b>: <r v=\"Luke.1.80\"></r>.†</s>"},"G306":{"l":"ἀναβάλλω","o":1,"ar":"<f><o>ἀνα-βάλλω</o>،</f> <s><b>أرجأ</b>، <b>أجّل</b>: الصيغة الوسطى، <r v=\"Acts.24.22\"></r>.†</s>","en":"<f><o>ἀνα-βάλλω</o>,</f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Ps.78.21\"></r> <r v=\"Ps.89.38\"></r> (<h n=\"H5674\">עבר</h>), <r v=\"1Sam.28.14\"></r>, <r v=\"Ps.104.2\"></r> (<h n=\"H5844\">עטה</h>);]</e> </et> <s><b>to defer</b>, <b>put off</b> (MM, <i>VGT</i>, s.v.): mid., <r v=\"Acts.24.22\"></r>.†</s>"},"G389":{"l":"ἀναστενάζω","o":1,"ar":"<f><o>ἀνα-στενάζω</o>،</f> <s><b>تنهّد من أعماقه</b>: <r v=\"Mark.8.12\"></r>.†</s>","en":"<f><o>ἀνα-στενάζω</o>,</f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Lam.1.4\"></r> (<h n=\"H584\">אנח</h> ni.), <r v=\"Sir.25.18\"></r> (<r v=\"Sir.25.17\"></r>), <r v=\"Sus.1.22\"></r>, <r v=\"2Macc.6.30\"></r>*;]</e> </et> <s><b>to sigh deeply</b>: <r v=\"Mark.8.12\"></r>.†</s>"},"G354":{"l":"ἀνάλημψις","o":1,"ar":"<f>* <o>ἀνά-λημψις</o>، <g>-εως, ἡ </g></f> <s><b>ارتفاع، أخذ إلى فوق</b>: <r v=\"Luke.9.51\"></r>.†</s>","en":"<f>* <o>ἀνά-λημψις</o>, <g>-εως, ἡ </g></f> <et> <e t=\"derivation\">(<g>κοινή</g> form of <g>ἀνάληψις</g>; v. <i>Th.</i>, <i>Gr.</i>, 108 f.),</e> </et> <s><b>a taking up</b>: <r v=\"Luke.9.51\"></r> (MM, <i>VGT</i>, s.v.).†</s>"},"G380":{"l":"ἀναπτύσσω","o":1,"ar":"<f><o>ἀνα-πτύσσω</o>،</f> <s><b>فتح (نشر) الدَّرج</b>: <g>τ. βιβλίον</g>، <r v=\"Luke.4.17\"></r>.†</s>","en":"<f><o>ἀνα-πτύσσω</o>,</f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H6566\">פּרשׂ</h>, etc.;]</e> </et> <s><b>to unroll</b>: <g>τ. βιβλίον</g>, <r v=\"Luke.4.17\"></r> (WH, R, <g>ἀνοίξας</g>).†</s>"}});A.got[3]=1})(window.ABBOTT=window.ABBOTT||{D:{},got:{}});